  3	// Kleine, reine Helfer für Geld und Datum der Finanz-Logik (keine Node-/React-Importe, auch im Browser nutzbar).
  4	// Datumswerte immer als ISO-Tag „JJJJ-MM-TT“ (Kalendertag, keine Uhrzeit), gerechnet in UTC – so gibt es keine
  5	// Sommerzeit-Sprünge. „Heute“ gilt in Europe/Vienna (Sitz der ÖkoInvest GmbH).
  6	
  7	/** Kaufmännisch auf Cent runden (EPSILON gegen 1,005 → 1,00) */
  8	export const rund2 = (x) => Math.round((Number(x) + Number.EPSILON) * 100) / 100;
  9	export const rund = (x, stellen = 2) => {
 10	  const f = 10 ** stellen;
 11	  return Math.round((Number(x) + Number.EPSILON) * f) / f;
 12	};
 13	export const summe = (liste, feld) => rund2(liste.reduce((s, x) => s + (Number(feld ? x[feld] : x) || 0), 0));
 14	
 15	const TAG = /^(\d{4})-(\d{2})-(\d{2})$/;
 16	
 17	export function istDatum(s) {
 18	  const m = TAG.exec(String(s || ""));
 19	  if (!m) return false;
 20	  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
 21	  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
 22	}
 23	
 24	export const datumOderLeer = (s) => (istDatum(s) ? String(s) : "");
 25	
 26	function alsDate(s) {
 27	  const m = TAG.exec(String(s));
 28	  if (!m) throw new Error(`Ungültiges Datum: ${s}`);
 29	  return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
 30	}
 31	const alsIso = (d) => d.toISOString().slice(0, 10);
 32	
 33	export function plusTage(s, n) {
 34	  const d = alsDate(s);
 35	  d.setUTCDate(d.getUTCDate() + Number(n || 0));
 36	  return alsIso(d);
 37	}
 38	
 39	/** Tage von a bis b (b − a), ganze Tage */
 40	export const tageZwischen = (a, b) => Math.round((alsDate(b) - alsDate(a)) / 86400000);
 41	
 42	/** Erster Tag des Monats + n Monate */
 43	export function monatsAnfang(jahr, monat) {
 44	  return alsIso(new Date(Date.UTC(jahr, monat - 1, 1)));
 45	}
 46	
 47	/** Letzter Tag des Monats (monat 1–12, darf über-/unterlaufen) */
 48	export function monatsEnde(jahr, monat) {
 49	  return alsIso(new Date(Date.UTC(jahr, monat, 0)));
 50	}
 51	
 52	export const jahrVon = (s) => Number(String(s).slice(0, 4));
 53	export const monatVon = (s) => Number(String(s).slice(5, 7));
 54	export const tageImJahr = (jahr) => (new Date(Date.UTC(jahr, 1, 29)).getUTCMonth() === 1 ? 366 : 365);
 55	
 56	/** „JJJJ-MM“ → erster und letzter Tag */
 57	export function monatsZeitraum(monat) {
 58	  const [j, m] = String(monat).split("-").map(Number);
 59	  return { von: monatsAnfang(j, m), bis: monatsEnde(j, m) };
 60	}
 61	
 62	/** Vormonat von „JJJJ-MM“ */
 63	export function vormonat(monat) {
 64	  const [j, m] = String(monat).split("-").map(Number);
 65	  return m === 1 ? `${j - 1}-12` : `${j}-${String(m - 1).padStart(2, "0")}`;
 66	}
 67	
 68	/** Heute (Europe/Vienna) als JJJJ-MM-TT */
 69	export function heute(jetzt = new Date()) {
 70	  return new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Vienna", year: "numeric", month: "2-digit", day: "2-digit" }).format(jetzt);
 71	}
 72	
 73	/** TT.MM.JJJJ für Texte und Belege */
 74	export function datumDe(s) {
 75	  if (!istDatum(s)) return "";
 76	  const [j, m, t] = String(s).split("-");
 77	  return `${t}.${m}.${j}`;
 78	}
 79	
 80	/** Betrag deutsch mit zwei Nachkommastellen, z. B. 12.345,67 € */
 81	export function euro(x) {
 82	  if (!Number.isFinite(Number(x))) return "–";
 83	  return `${Number(x).toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;
 84	}
 85	
 86	export function zahlDe(x, stellen = 0) {
 87	  if (!Number.isFinite(Number(x))) return "–";
 88	  return Number(x).toLocaleString("de-DE", { minimumFractionDigits: stellen, maximumFractionDigits: stellen });
 89	}
