  1	// src/lib/plattform/finanzen/afa.js
  2	//
  3	// Anlagenbuchhaltung: lineare Abschreibung (AfA) eigener Contracting-Anlagen und Projektcontrolling – reine Funktionen.
  4	// Maßgeblich im Betrieb ist der Abschreibungsplan des ERPNext-Assets; diese Funktionen liefern Vorschau und Demo.
  5	
  6	import { AFA } from "./konstanten.js";
  7	import { istDatum, jahrVon, monatVon, rund2 } from "./basis.js";
  8	
  9	/**
 10	 * AfA-Plan linear.
 11	 * { anschaffungswert, nutzungsdauerJahre, inbetriebnahme (JJJJ-MM-TT), regel: AT | DE | CH, restwert = 0 }
 12	 *   AT: Halbjahresregel – Inbetriebnahme nach dem 30.6. → im ersten Jahr halbe Jahres-AfA, Rest im Jahr nach Ablauf
 13	 *   DE/CH: monatsgenau – im ersten Jahr (13 − Monat)/12 der Jahres-AfA
 14	 * Rückgabe [{ jahr, afa, restbuchwert }]
 15	 */
 16	export function afaPlan({ anschaffungswert, nutzungsdauerJahre, inbetriebnahme, regel = "AT", restwert = 0 }) {
 17	  const basis = rund2(Number(anschaffungswert) - Number(restwert || 0));
 18	  const nd = Math.round(Number(nutzungsdauerJahre) || 0);
 19	  if (!(basis > 0) || !(nd > 0) || !istDatum(inbetriebnahme)) return [];
 20	  const jahres = basis / nd;
 21	  const j0 = jahrVon(inbetriebnahme);
 22	  const m0 = monatVon(inbetriebnahme);
 23	  const ersterAnteil = regel === "AT" ? (m0 > 6 ? 0.5 : 1) : (13 - m0) / 12;
 24	  const plan = [];
 25	  let rest = basis;
 26	  for (let i = 0; rest > 0.004 && i <= nd + 1; i++) {
 27	    const soll = i === 0 ? jahres * ersterAnteil : jahres;
 28	    const afa = rund2(Math.min(rest, soll));
 29	    rest = rund2(rest - afa);
 30	    plan.push({ jahr: j0 + i, afa, restbuchwert: rund2(rest + Number(restwert || 0)) });
 31	  }
 32	  return plan;
 33	}
