 35	/** Buchwert zum Jahresende eines Jahres */
 36	export function buchwert(plan, jahr, anschaffungswert) {
 37	  const z = plan.filter((p) => p.jahr <= jahr).pop();
 38	  return z ? z.restbuchwert : rund2(anschaffungswert);
 39	}
