 43	/**
 44	 * Projektcontrolling: Budget vs. Ist eines Entwicklungsprojekts.
 45	 * kosten [{kostenart, betrag}], budget (Gesamt oder {kostenart: betrag}), mwp
 46	 */
 47	export function budgetVergleich({ kosten = [], budget = null, mwp = null }) {
 48	  const ist = rund2(kosten.reduce((s, k) => s + (Number(k.betrag) || 0), 0));
 49	  const jeArt = {};
 50	  for (const k of kosten) jeArt[k.kostenart || "sonstiges"] = rund2((jeArt[k.kostenart || "sonstiges"] || 0) + (Number(k.betrag) || 0));
 51	  const budgetGesamt = budget === null ? null : typeof budget === "number" ? budget : rund2(Object.values(budget).reduce((s, x) => s + (Number(x) || 0), 0));
 52	  const quote = budgetGesamt ? ist / budgetGesamt : null;
 53	  return {
 54	    ist, jeArt, budget: budgetGesamt,
 55	    abweichung: budgetGesamt === null ? null : rund2(ist - budgetGesamt),
 56	    quote: quote === null ? null : Math.round(quote * 1000) / 1000,
 57	    ampel: quote === null ? "offen" : quote > 1 ? "rot" : quote > 0.85 ? "gelb" : "gruen",
 58	    jeMwp: Number(mwp) > 0 ? rund2(ist / Number(mwp)) : null,
 59	  };
 60	}
