 62	//
 63	// Contracting-Abrechnung je Anlage und Monat aus den Zählerstand-Monatswerten der ABRECHNUNGSRELEVANTEN (geeichten)
 64	// Messpunkte – reine Funktionen. MQTT-/Monitoring-Werte werden nie abgerechnet.
 65	//
 66	// Gelieferter PV-Strom = Erzeugung (Erzeugungszähler, Register 2.8.0) − Einspeisung ins Netz (Zweirichtungszähler am
 67	// Netzverknüpfungspunkt, Register 2.8.0). Ohne Erzeugungszähler, aber mit Verbrauchszähler: Verbrauch (1.8.0).
 68	// Rechnung = geliefert × Arbeitspreis (ggf. indexiert) + Grundgebühr.
 69	//
 70	// Plausibilität (sonst KLÄRFALL statt Rechnung):
 71	//   - Monatswert fehlt für einen abrechnungsrelevanten Messpunkt/Register
 72	//   - Menge fehlt (kein Vormonatsstand – z. B. erster Monat oder Zählertausch)
 73	//   - geliefert < 0 oder Erzeugung > 270 kWh je kWp im Monat (physikalisch unplausibel)
 74	
 75	import { datumDe, jahrVon, monatVon, monatsZeitraum, rund, rund2, summe, zahlDe } from "./basis.js";
 76	import { indexiertePacht } from "./indexierung.js";
 77	
 78	const REIHE_LAND = { DE: "VPI-DE-2020", AT: "VPI-AT-2020", CH: "LIK-CH-2020" };
 79	
 80	export const MAX_KWH_JE_KWP_MONAT = 270;
 81	
 82	/**
 83	 * Arbeitspreis in ct/kWh nach der Preisgleitung des Vertrags (`indexBasis`, Anlagen-Modul):
 84	 *   fest        kein Gleitung
 85	 *   prozent     + indexierungPct % p. a. je volles Vertragsjahr
 86	 *   vpi         wie die Pacht-Wertsicherung: jährlich zum 1.1. mit dem VPI-Jahresdurchschnitt des Vorjahres (Basis: Jahr vor Beginn)
 87	 *   strompreis  Strompreisindex – nicht hinterlegt → `fehlt` (Klärfall statt falscher Rechnung)
 88	 * Ohne indexBasis gilt „prozent“, wenn indexierungPct > 0, sonst „fest“.
 89	 */
 90	export function arbeitspreis(vertrag, monat, { indexTabelle = [], land = "DE" } = {}) {
 91	  const basis = Number(vertrag.strompreisCt) || 0;
 92	  const pct = Number(vertrag.indexierungPct) || 0;
 93	  const art = vertrag.indexBasis || (pct ? "prozent" : "fest");
 94	  const [j, m] = String(monat).split("-").map(Number);
 95	  if (art === "fest" || !vertrag.beginn) return { ct: rund(basis, 3), jahre: 0, art };
 96	  if (art === "strompreis") return { ct: rund(basis, 3), jahre: 0, art, fehlt: "Preisgleitung nach Strompreisindex vereinbart – Indexwerte sind nicht hinterlegt. Arbeitspreis bitte manuell festlegen." };
 97	  if (art === "vpi") {
 98	    const reihe = REIHE_LAND[land] || "VPI-AT-2020";
 99	    const r = indexiertePacht({ basisBetrag: basis * 1000, basisJahr: jahrVon(vertrag.beginn) - 1, reihe, tabelle: indexTabelle }, j);
100	    return { ct: rund(r.betrag / 1000, 3), jahre: 0, art, reihe, fehlt: r.fehlt?.length ? `Indexwert fehlt (${reihe}, ${r.fehlt.join(", ")}) – bitte unter „Index (VPI)“ nachtragen.` : null };
101	  }
102	  let jahre = j - jahrVon(vertrag.beginn);
103	  if (m < monatVon(vertrag.beginn)) jahre -= 1;
104	  jahre = Math.max(0, jahre);
105	  return { ct: rund(basis * (1 + pct / 100) ** jahre, 3), jahre, art };
106	}
107	
108	/**
109	 * Abrechnung eines Monats.
110	 * eingabe: { vertrag {strompreisCt, grundgebuehrMonat, indexierungPct, beginn, status}, anlage {id, name, kwp}, monat "JJJJ-MM",
111	 *            messpunkte [{id, art, abrechnungsrelevant, zaehlernummer, bezeichnung}], zeilen [Monatswerte: {monat, messpunktId, register, stand, menge, geprueft, quelle}] }
112	 * Rückgabe { ok, klaerung[], positionen[], netto, gelieferteKwh, zaehlerstaende[], hinweise[] }
113	 */
114	export function contractingAbrechnen({ vertrag, anlage, monat, messpunkte = [], zeilen = [], indexTabelle = [] }) {
115	  const klaerung = [];
116	  const hinweise = [];
117	  const zaehlerstaende = [];
118	  if (!vertrag) return { ok: false, klaerung: ["Kein Contracting-Vertrag hinterlegt."], positionen: [], netto: 0 };
119	  const relevant = messpunkte.filter((m) => m.abrechnungsrelevant);
120	  const preis = arbeitspreis(vertrag, monat, { indexTabelle, land: anlage?.land });
121	  const mitArbeit = preis.ct > 0;
122	  if (mitArbeit && preis.fehlt) klaerung.push(preis.fehlt);
123	  if (Number(vertrag.mindestabnahmeKwhJahr) > 0) hinweise.push(`Mindestabnahme ${zahlDe(vertrag.mindestabnahmeKwhJahr)} kWh/Jahr vereinbart – ein Ausgleich (Take-or-Pay) erfolgt in der Jahresabrechnung, nicht monatlich.`);
124	  const wert = (mp, reg) => zeilen.find((z) => z.monat === monat && z.messpunktId === mp.id && z.register === reg);
125	  const menge = (art, reg) => {
126	    let s = 0;
127	    let gefunden = false;
128	    for (const mp of relevant.filter((m) => m.art === art)) {
129	      const w = wert(mp, reg);
130	      if (!w) {
131	        klaerung.push(`Monatswert ${monat} fehlt: Zähler ${mp.zaehlernummer} (${mp.bezeichnung || art}), Register ${reg}.`);
132	        continue;
133	      }
134	      if (w.menge === null || w.menge === undefined) {
135	        klaerung.push(`Menge ${monat} nicht berechenbar (Vormonatsstand fehlt): Zähler ${mp.zaehlernummer}, Register ${reg}.`);
136	        continue;
137	      }
138	      gefunden = true;
139	      if (!w.geprueft) hinweise.push(`Zählerstand ${mp.zaehlernummer}/${reg} noch nicht als geprüft markiert (${w.quelle || "Quelle unbekannt"}).`);
140	      zaehlerstaende.push({ zaehlernummer: mp.zaehlernummer, bezeichnung: mp.bezeichnung || "", register: reg, anfang: rund(Number(w.stand) - Number(w.menge), 3), ende: Number(w.stand), menge: Number(w.menge) });
141	      s += Number(w.menge);
142	    }
143	    return gefunden ? s : null;
144	  };
145	
146	  let gelieferteKwh = 0;
147	  if (mitArbeit) {
148	    const hatErz = relevant.some((m) => m.art === "erzeugung");
149	    const hatVerbrauch = relevant.some((m) => m.art === "verbrauch");
150	    if (hatErz) {
151	      const erz = menge("erzeugung", "2.8.0");
152	      const einsp = relevant.some((m) => m.art === "zweirichtung") ? menge("zweirichtung", "2.8.0") : 0;
153	      if (erz !== null && einsp !== null) {
154	        gelieferteKwh = Math.round(erz - einsp);
155	        if (gelieferteKwh < 0) klaerung.push(`Einspeisung (${zahlDe(einsp)} kWh) größer als Erzeugung (${zahlDe(erz)} kWh) – Zählerzuordnung prüfen.`);
156	        if (Number(anlage?.kwp) > 0 && erz > Number(anlage.kwp) * MAX_KWH_JE_KWP_MONAT) klaerung.push(`Erzeugung ${zahlDe(erz)} kWh unplausibel hoch für ${zahlDe(anlage.kwp)} kWp (> ${MAX_KWH_JE_KWP_MONAT} kWh/kWp im Monat).`);
157	      }
158	    } else if (hatVerbrauch) {
159	      const v = menge("verbrauch", "1.8.0");
160	      if (v !== null) gelieferteKwh = Math.round(v);
161	    } else {
162	      klaerung.push("Kein abrechnungsrelevanter Erzeugungs- oder Verbrauchszähler – Arbeitspreis kann nicht abgerechnet werden.");
163	    }
164	  }
165	  if (klaerung.length) return { ok: false, klaerung, positionen: [], netto: 0, gelieferteKwh: null, zaehlerstaende, hinweise };
166	
167	  const z = monatsZeitraum(monat);
168	  const positionen = [];
169	  if (mitArbeit) {
170	    positionen.push({
171	      art: "arbeit", artikel: "CONTRACTING-STROM",
172	      text: `PV-Strom ${datumDe(z.von)} – ${datumDe(z.bis)}: ${zahlDe(gelieferteKwh)} kWh × ${zahlDe(preis.ct, 3)} ct/kWh${preis.jahre ? ` (indexiert, ${preis.jahre}. Vertragsjahr +${zahlDe(vertrag.indexierungPct, 2)} % p. a.)` : preis.art === "vpi" && preis.ct !== rund(vertrag.strompreisCt, 3) ? ` (wertgesichert nach ${preis.reihe}, Ausgangspreis ${zahlDe(vertrag.strompreisCt, 3)} ct)` : ""}`,
173	      menge: gelieferteKwh, einheit: "kWh", preis: rund(preis.ct / 100, 5), betrag: rund2((gelieferteKwh * preis.ct) / 100),
174	    });
175	  }
176	  if (Number(vertrag.grundgebuehrMonat) > 0) {
177	    positionen.push({ art: "grund", artikel: "CONTRACTING-GRUND", text: `Grundgebühr ${monat.slice(5)}/${monat.slice(0, 4)}`, menge: 1, einheit: "Monat", preis: rund2(vertrag.grundgebuehrMonat), betrag: rund2(vertrag.grundgebuehrMonat) });
178	  }
179	  if (!positionen.length) return { ok: false, klaerung: ["Weder Arbeitspreis noch Grundgebühr vereinbart – nichts abzurechnen."], positionen: [], netto: 0, zaehlerstaende, hinweise };
180	  return { ok: true, klaerung: [], positionen, netto: summe(positionen, "betrag"), gelieferteKwh: mitArbeit ? gelieferteKwh : null, arbeitspreisCt: preis.ct, zaehlerstaende, hinweise };
181	}
182	// src/lib/plattform/finanzen/faelligkeit.js
183	//
184	// Abrechnungsperioden und Fälligkeiten eines Pachtvertrags – reine Funktionen.
185	//
186	// Perioden sind kalendergebunden (Jahr, Halbjahr, Quartal, Monat). Beginnt oder endet der Vertrag innerhalb einer
187	// Periode, wird taggenau anteilig gerechnet (`anteil` = Vertragstage / Periodentage).
188	//
189	// Phasen:
190	//   reservierung  vom Vertragsdatum bis zum Tag vor dem Pachtbeginn (Baubeginn/Inbetriebnahme). Ist der Beginn noch
191	//                 offen, laufen die Perioden bis zum Stichtag. Die Reservierungsprämie wird IMMER nachschüssig
192	//                 abgerechnet – so entsteht beim späteren Pachtbeginn keine Rückforderung.
193	//   pacht         vom Pachtbeginn bis zum Laufzeitende (Beginn + Laufzeit − 1 Tag), Zahlweise laut Vertrag.
194	//
195	// Fällig: vorschüssig am ersten Tag der Periode + Zahlungsziel, nachschüssig am Tag nach Periodenende + Zahlungsziel.
196	// Abgerechnet (Gutschrift erzeugt) wird eine Periode, sobald der Erstellungstag erreicht ist:
197	//   vorschüssig   `vorlaufTage` vor der Fälligkeit (Eigentümer erhält die Gutschrift rechtzeitig)
198	//   nachschüssig  nach Ablauf der Periode
199	
200	import { RHYTHMEN } from "./konstanten.js";
201	import { istDatum, jahrVon, monatVon, monatsAnfang, monatsEnde, plusTage, tageZwischen } from "./basis.js";
202	
203	/** Kalenderperiode, die den Tag `datum` enthält */
204	export function periodeVon(datum, rhythmus) {
205	  const monate = RHYTHMEN[rhythmus]?.monate || 12;
206	  const j = jahrVon(datum);
207	  const startMonat = Math.floor((monatVon(datum) - 1) / monate) * monate + 1;
208	  return { von: monatsAnfang(j, startMonat), bis: monatsEnde(j, startMonat + monate - 1) };
209	}
210	
211	/** Perioden zwischen ab und bis (beide inklusive, bis optional = offen, dann bis `stopp`) */
212	export function perioden({ ab, bis = null, rhythmus = "jaehrlich", stopp }) {
213	  if (!istDatum(ab)) return [];
214	  const ende = bis && istDatum(bis) ? bis : stopp;
215	  if (!ende || ende < ab) return [];
216	  const liste = [];
217	  let p = periodeVon(ab, rhythmus);
218	  for (let i = 0; i < 1200 && p.von <= ende; i++) {
219	    const von = ab > p.von ? ab : p.von;
220	    const bisTag = bis && bis < p.bis ? bis : p.bis;
221	    const tageVoll = tageZwischen(p.von, p.bis) + 1;
222	    const tage = tageZwischen(von, bisTag) + 1;
223	    liste.push({ periodeVon: p.von, periodeBis: p.bis, von, bis: bisTag, tage, tageVoll, anteil: tage / tageVoll, monate: RHYTHMEN[rhythmus]?.monate || 12 });
224	    p = periodeVon(plusTage(p.bis, 1), rhythmus);
225	  }
226	  return liste;
227	}
228	
229	/** Laufzeitende = Beginn + Laufzeit (Jahre) − 1 Tag */
230	export function laufzeitEnde(beginn, laufzeitJahre) {
231	  if (!istDatum(beginn) || !(Number(laufzeitJahre) > 0)) return null;
232	  const j = jahrVon(beginn) + Number(laufzeitJahre);
233	  const md = String(beginn).slice(4);
234	  const ziel = md === "-02-29" ? `${j}-02-28` : `${j}${md}`;
235	  return plusTage(ziel, istDatum(ziel) ? -1 : 0);
236	}
237	
238	/**
239	 * Alle Fälligkeiten eines Vertrags bis `stichtag` (inkl. künftiger Perioden bis `ausblickBis` für „nächste Zahlung“).
240	 * vertrag: { id, vertragsdatum, beginn, laufzeitJahre, faelligkeit, zahlweise, zahlungszielTage, reservierungJahr, vorlaufTage }
241	 * Rückgabe: [{ schluessel, phase, von, bis, anteil, faktorJahr, faelligAm, erstellbarAb, zahlweise }]
242	 */
243	export function faelligkeiten(vertrag, { stichtag, ausblickBis = null } = {}) {
244	  const rhythmus = RHYTHMEN[vertrag.faelligkeit] ? vertrag.faelligkeit : "jaehrlich";
245	  const ziel = Math.max(0, Number(vertrag.zahlungszielTage ?? 14));
246	  const vorlauf = Math.max(0, Number(vertrag.vorlaufTage ?? 14));
247	  const stopp = ausblickBis && ausblickBis > stichtag ? ausblickBis : stichtag;
248	  const ergebnis = [];
249	  const eintrag = (phase, p, zahlweise) => {
250	    const faelligAm = zahlweise === "vorschuessig" ? plusTage(p.von, ziel) : plusTage(p.bis, 1 + ziel);
251	    const erstellbarAb = zahlweise === "vorschuessig" ? plusTage(faelligAm, -vorlauf - ziel) : plusTage(p.bis, 1);
252	    ergebnis.push({
253	      schluessel: `${vertrag.id}:${phase}:${p.von}`,
254	      phase, von: p.von, bis: p.bis, anteil: p.anteil, tage: p.tage, tageVoll: p.tageVoll,
255	      // Anteil eines Jahresbetrags: Periodenlänge in Monaten / 12 × taggenauer Anteil
256	      faktorJahr: (p.monate / 12) * p.anteil,
257	      faelligAm, erstellbarAb, zahlweise,
258	    });
259	  };
260	  // Reservierungsprämie bis zum Pachtbeginn (nachschüssig)
261	  if (Number(vertrag.reservierungJahr) > 0 && istDatum(vertrag.vertragsdatum)) {
262	    const resBis = istDatum(vertrag.beginn) ? plusTage(vertrag.beginn, -1) : null;
263	    if (!resBis || resBis >= vertrag.vertragsdatum) {
264	      // offener Beginn: Perioden werden fortgeschrieben; abgerechnet wird erst nach Periodenende (nachschüssig)
265	      for (const p of perioden({ ab: vertrag.vertragsdatum, bis: resBis, rhythmus, stopp })) eintrag("reservierung", p, "nachschuessig");
266	    }
267	  }
268	  if (istDatum(vertrag.beginn)) {
269	    const ende = laufzeitEnde(vertrag.beginn, vertrag.laufzeitJahre);
270	    for (const p of perioden({ ab: vertrag.beginn, bis: ende, rhythmus, stopp })) eintrag("pacht", p, vertrag.zahlweise === "vorschuessig" ? "vorschuessig" : "nachschuessig");
271	  }
272	  return ergebnis;
273	}
274	
275	/** Fällige (abzurechnende) Perioden zum Stichtag */
276	export const abzurechnen = (vertrag, stichtag) => faelligkeiten(vertrag, { stichtag }).filter((f) => f.erstellbarAb <= stichtag);
277	
278	/** Nächste künftige Zahlung ab Stichtag (für „nächste Zahlung“ im Portal) */
279	export function naechsteFaelligkeit(vertrag, stichtag) {
280	  const bis = plusTage(stichtag, 800);
281	  return faelligkeiten(vertrag, { stichtag, ausblickBis: bis }).find((f) => f.faelligAm >= stichtag) || null;
282	}
