300	// src/lib/plattform/finanzen/indexierung.js
301	//
302	// Wertsicherung (Indexierung) einer Jahrespacht über einen Verbraucherpreisindex – reine Funktionen.
303	//
304	// Regel (je Vertrag einstellbar):
305	//   basisBetrag   Jahrespacht bei Vertragsschluss (€)
306	//   basisJahr     Jahr des Basisindex (Jahresdurchschnitt), basisIndex optional (sonst aus der Tabelle)
307	//   reihe         Index-Reihe (VPI-AT-2020, VPI-DE-2020, LIK-CH-2020)
308	//   schwellePct   Anpassung erst, wenn die Änderung seit der letzten Anpassung die Schwelle erreicht (0 = jährlich)
309	//   anteilPct     Weitergabe der Änderung in % (100 = voll)
310	//   nurErhoehung  nur Erhöhungen weitergeben (Hinweis: in DE nach § 2 Abs. 3 PrKG problematisch – Klauseln müssen
311	//                 in der Regel in beide Richtungen wirken; mit Rechtsberatung prüfen)
312	//
313	// Anpassung zum 1.1. jedes Jahres J ab dem ersten Abrechnungsjahr nach dem Basisjahr: Vergleich Jahresdurchschnitt
314	// J−1 mit dem Index der letzten Anpassung. Neue Pacht = alte Pacht × (1 + Anteil × (I(J−1) / I(letzte) − 1)).
315	// Fehlt ein Indexwert, bleibt der letzte Betrag stehen und das Ergebnis meldet `fehlt` (→ Klärfall).
316	
317	import { euro, rund, rund2, zahlDe } from "./basis.js";
318	
319	/** Indexwert aus der Tabelle [{reihe, jahr, wert}] */
320	export function indexWert(tabelle, reihe, jahr) {
321	  const t = (tabelle || []).find((x) => x.reihe === reihe && Number(x.jahr) === Number(jahr));
322	  return t && Number.isFinite(Number(t.wert)) && Number(t.wert) > 0 ? Number(t.wert) : null;
323	}
324	
325	/**
326	 * Verlauf der Wertsicherung bis einschließlich `bisJahr`.
327	 * Rückgabe { schritte: [{jahr, referenzJahr, index, basisIndex, aenderungPct, angepasst, betrag, text}], betrag, fehlt: [jahr…] }
328	 */
329	export function indexVerlauf({ basisBetrag, basisJahr, basisIndex, reihe, tabelle, bisJahr, schwellePct = 0, anteilPct = 100, nurErhoehung = false }) {
330	  const start = Number(basisIndex) > 0 ? Number(basisIndex) : indexWert(tabelle, reihe, basisJahr);
331	  let betrag = rund2(basisBetrag);
332	  const schritte = [];
333	  const fehlt = [];
334	  if (!start) {
335	    return { schritte, betrag, fehlt: [Number(basisJahr)], basisIndex: null };
336	  }
337	  let letzterIndex = start;
338	  const anteil = Math.max(0, Math.min(100, Number(anteilPct ?? 100))) / 100;
339	  const schwelle = Math.max(0, Number(schwellePct) || 0) / 100;
340	  for (let jahr = Number(basisJahr) + 1; jahr <= Number(bisJahr); jahr++) {
341	    const ref = jahr - 1;
342	    const idx = ref === Number(basisJahr) ? start : indexWert(tabelle, reihe, ref);
343	    if (!idx) {
344	      fehlt.push(ref);
345	      schritte.push({ jahr, referenzJahr: ref, index: null, basisIndex: letzterIndex, aenderungPct: null, angepasst: false, betrag, text: `Indexwert ${ref} fehlt – Betrag unverändert` });
346	      continue;
347	    }
348	    const aenderung = idx / letzterIndex - 1;
349	    let angepasst = false;
350	    let text;
351	    if (Math.abs(aenderung) < 1e-12) text = "keine Indexänderung";
352	    else if (nurErhoehung && aenderung < 0) text = "Index gesunken – vereinbart ist nur eine Erhöhung";
353	    else if (Math.abs(aenderung) + 1e-12 < schwelle) text = `Änderung ${zahlDe(aenderung * 100, 2)} % unter der Schwelle von ${zahlDe(schwelle * 100, 2)} %`;
354	    else {
355	      const alt = betrag;
356	      betrag = rund2(betrag * (1 + anteil * aenderung));
357	      angepasst = true;
358	      text = `Anpassung ${aenderung > 0 ? "+" : ""}${zahlDe(aenderung * anteil * 100, 2)} % (Index ${zahlDe(letzterIndex, 1)} → ${zahlDe(idx, 1)}${anteil < 1 ? `, ${zahlDe(anteil * 100, 0)} % weitergegeben` : ""}): ${euro(alt)} → ${euro(betrag)}`;
359	    }
360	    schritte.push({ jahr, referenzJahr: ref, index: idx, basisIndex: letzterIndex, aenderungPct: rund(aenderung * 100, 3), angepasst, betrag, text });
361	    if (angepasst) letzterIndex = idx;
362	  }
363	  return { schritte, betrag, fehlt, basisIndex: start };
364	}
