367	export function indexiertePacht(regel, jahr) {
368	  if (Number(jahr) <= Number(regel.basisJahr)) return { betrag: rund2(regel.basisBetrag), schritte: [], fehlt: [], basisIndex: regel.basisIndex || null };
369	  return indexVerlauf({ ...regel, bisJahr: jahr });
370	}
