84	    84	/** Monate („JJJJ-MM“) eines Zeitraums – für die Ertragssumme der Umsatzbeteiligung */
85	    85	export function monateImZeitraum(von, bis) {
86	    86	  const liste = [];
87	    87	  let [j, m] = [jahrVon(von), Number(String(von).slice(5, 7))];
88	    88	  const [jb, mb] = [jahrVon(bis), Number(String(bis).slice(5, 7))];
89	    89	  while (j < jb || (j === jb && m <= mb)) {
90	    90	    liste.push(`${j}-${String(m).padStart(2, "0")}`);
91	    91	    m += 1;
92	    92	    if (m > 12) {
93	    93	      m = 1;
94	    94	      j += 1;
95	    95	    }
96	    96	  }
97	    97	  return liste;
98	    98	}
