100	   100	/**
101	   101	 * Erzeugung (kWh) einer Periode aus Zählerstand-Monatswerten (nur Register 2.8.0 der Erzeugungszähler).
102	   102	 * Teilmonate am Rand werden taggenau anteilig gerechnet. Rückgabe { kwh, fehlt: [monat…] }
103	   103	 */
104	   104	export function ertragAusMonatswerten(zeilen, messpunkte, von, bis) {
105	   105	  const erz = new Set((messpunkte || []).filter((m) => m.art === "erzeugung" && m.abrechnungsrelevant).map((m) => m.id));
106	   106	  const fehlt = [];
107	   107	  let kwh = 0;
108	   108	  if (!erz.size) return { kwh: null, fehlt: ["kein abrechnungsrelevanter Erzeugungszähler"] };
109	   109	  for (const monat of monateImZeitraum(von, bis)) {
110	   110	    const werte = (zeilen || []).filter((z) => z.monat === monat && erz.has(z.messpunktId) && z.register === "2.8.0");
111	   111	    if (werte.length < erz.size || werte.some((w) => w.menge === null || w.menge === undefined)) {
112	   112	      fehlt.push(monat);
113	   113	      continue;
114	   114	    }
115	   115	    const [j, mm] = monat.split("-").map(Number);
116	   116	    const tageMonat = new Date(Date.UTC(j, mm, 0)).getUTCDate();
117	   117	    const start = monat === String(von).slice(0, 7) ? Number(String(von).slice(8)) : 1;
118	   118	    const ende = monat === String(bis).slice(0, 7) ? Number(String(bis).slice(8)) : tageMonat;
119	   119	    kwh += werte.reduce((s, w) => s + Number(w.menge), 0) * ((ende - start + 1) / tageMonat);
120	   120	  }
121	   121	  return { kwh: fehlt.length ? null : Math.round(kwh), fehlt };
122	   122	}
