239	   239	/**
240	   240	 * pain.001.001.09 erzeugen.
241	   241	 * auftrag: { nachrichtId, erstelltAm (ISO), ausfuehrungAm (JJJJ-MM-TT), auftraggeber: {name, iban, bic?},
242	   242	 *           zahlungen: [{ endToEndId, betrag, name, iban, bic?, verwendungszweck }] }
243	   243	 * Wirft Error bei ungültigen Daten (IBAN, Betrag ≤ 0, leere Liste) – die Aufrufer prüfen vorher und melden verständlich.
244	   244	 */
245	   245	export function pain001(auftrag) {
246	   246	  const { nachrichtId, erstelltAm, ausfuehrungAm, auftraggeber, zahlungen } = auftrag;
247	   247	  if (!zahlungen?.length) throw new Error("Keine Zahlungen");
248	   248	  if (!ibanPruefen(auftraggeber?.iban)) throw new Error("IBAN des Auftraggebers ungültig");
249	   249	  if (!/^\d{4}-\d{2}-\d{2}$/.test(ausfuehrungAm || "")) throw new Error("Ausführungsdatum ungültig");
250	   250	  for (const z of zahlungen) {
251	   251	    if (!ibanPruefen(z.iban)) throw new Error(`IBAN ungültig (${z.endToEndId})`);
252	   252	    if (!(rund2(z.betrag) > 0)) throw new Error(`Betrag ungültig (${z.endToEndId})`);
253	   253	    if (z.bic && !bicPruefen(z.bic)) throw new Error(`BIC ungültig (${z.endToEndId})`);
254	   254	  }
255	   255	  const anzahl = zahlungen.length;
256	   256	  const summe = betragText(zahlungen.reduce((s, z) => s + rund2(z.betrag), 0));
257	   257	  const msgId = sepaId(nachrichtId);
258	   258	  const zeit = String(erstelltAm || new Date().toISOString()).replace(/\.\d{3}Z$/, "Z");
259	   259	  const agBic = auftraggeber.bic && bicPruefen(auftraggeber.bic) ? `<FinInstnId><BICFI>${xml(auftraggeber.bic.toUpperCase())}</BICFI></FinInstnId>` : "<FinInstnId><Othr><Id>NOTPROVIDED</Id></Othr></FinInstnId>";
260	   260	  const tx = zahlungen
261	   261	    .map((z) => {
262	   262	      const cdtrAgt = z.bic && bicPruefen(z.bic) ? `\n        <CdtrAgt><FinInstnId><BICFI>${xml(z.bic.toUpperCase())}</BICFI></FinInstnId></CdtrAgt>` : "";
263	   263	      return `      <CdtTrfTxInf>
264	   264	        <PmtId><EndToEndId>${xml(sepaId(z.endToEndId) || "NOTPROVIDED")}</EndToEndId></PmtId>
265	   265	        <Amt><InstdAmt Ccy="EUR">${betragText(z.betrag)}</InstdAmt></Amt>${cdtrAgt}
266	   266	        <Cdtr><Nm>${xml(sepaText(z.name, 70))}</Nm></Cdtr>
267	   267	        <CdtrAcct><Id><IBAN>${xml(ibanNormalisieren(z.iban))}</IBAN></Id></CdtrAcct>
268	   268	        <RmtInf><Ustrd>${xml(sepaText(z.verwendungszweck, 140))}</Ustrd></RmtInf>
269	   269	      </CdtTrfTxInf>`;
270	   270	    })
271	   271	    .join("\n");
272	   272	  return `<?xml version="1.0" encoding="UTF-8"?>
273	   273	<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pain.001.001.09" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="urn:iso:std:iso:20022:tech:xsd:pain.001.001.09 pain.001.001.09.xsd">
274	   274	  <CstmrCdtTrfInitn>
275	   275	    <GrpHdr>
276	   276	      <MsgId>${xml(msgId)}</MsgId>
277	   277	      <CreDtTm>${xml(zeit)}</CreDtTm>
278	   278	      <NbOfTxs>${anzahl}</NbOfTxs>
279	   279	      <CtrlSum>${summe}</CtrlSum>
280	   280	      <InitgPty><Nm>${xml(sepaText(auftraggeber.name, 70))}</Nm></InitgPty>
281	   281	    </GrpHdr>
282	   282	    <PmtInf>
283	   283	      <PmtInfId>${xml(sepaId(`${msgId}-1`))}</PmtInfId>
284	   284	      <PmtMtd>TRF</PmtMtd>
285	   285	      <BtchBookg>true</BtchBookg>
286	   286	      <NbOfTxs>${anzahl}</NbOfTxs>
287	   287	      <CtrlSum>${summe}</CtrlSum>
288	   288	      <PmtTpInf><SvcLvl><Cd>SEPA</Cd></SvcLvl></PmtTpInf>
289	   289	      <ReqdExctnDt><Dt>${xml(ausfuehrungAm)}</Dt></ReqdExctnDt>
290	   290	      <Dbtr><Nm>${xml(sepaText(auftraggeber.name, 70))}</Nm></Dbtr>
291	   291	      <DbtrAcct><Id><IBAN>${xml(ibanNormalisieren(auftraggeber.iban))}</IBAN></Id></DbtrAcct>
292	   292	      <DbtrAgt>${agBic}</DbtrAgt>
293	   293	      <ChrgBr>SLEV</ChrgBr>
294	   294	${tx}
295	   295	    </PmtInf>
296	   296	  </CstmrCdtTrfInitn>
297	   297	</Document>
298	   298	`;
299	   299	}
