301	   301	/**
302	   302	 * Strukturprüfung einer pain.001-Datei (ohne XSD): Namespace, Pflichtelemente, Anzahl/Kontrollsumme, IBANs,
303	   303	 * Beträge mit zwei Nachkommastellen, Kennungen ≤ 35 Zeichen. Liefert Liste der Fehler (leer = in Ordnung).
304	   304	 */
305	   305	export function pain001Pruefen(text) {
306	   306	  const f = [];
307	   307	  const s = String(text || "");
308	   308	  if (!s.startsWith('<?xml version="1.0" encoding="UTF-8"?>')) f.push("XML-Deklaration fehlt");
309	   309	  if (!s.includes('xmlns="urn:iso:std:iso:20022:tech:xsd:pain.001.001.09"')) f.push("Namespace pain.001.001.09 fehlt");
310	   310	  for (const tag of ["CstmrCdtTrfInitn", "GrpHdr", "MsgId", "CreDtTm", "NbOfTxs", "CtrlSum", "InitgPty", "PmtInf", "PmtInfId", "PmtMtd", "ReqdExctnDt", "Dbtr", "DbtrAcct", "DbtrAgt", "ChrgBr"]) {
311	   311	    if (!new RegExp(`<${tag}[ >]`).test(s)) f.push(`Element ${tag} fehlt`);
312	   312	  }
313	   313	  const auf = (s.match(/<[A-Za-z]+[ >]/g) || []).length;
314	   314	  const zu = (s.match(/<\/[A-Za-z]+>/g) || []).length;
315	   315	  if (auf !== zu) f.push("Elemente nicht ausgeglichen geöffnet/geschlossen");
316	   316	  const txs = s.match(/<CdtTrfTxInf>[\s\S]*?<\/CdtTrfTxInf>/g) || [];
317	   317	  const betraege = [...s.matchAll(/<InstdAmt Ccy="EUR">([^<]+)<\/InstdAmt>/g)].map((m) => m[1]);
318	   318	  const nb = [...s.matchAll(/<NbOfTxs>(\d+)<\/NbOfTxs>/g)].map((m) => Number(m[1]));
319	   319	  const ctrl = [...s.matchAll(/<CtrlSum>([^<]+)<\/CtrlSum>/g)].map((m) => m[1]);
320	   320	  if (!txs.length) f.push("Keine Transaktionen");
321	   321	  if (nb.some((x) => x !== txs.length)) f.push("NbOfTxs passt nicht zur Anzahl der Transaktionen");
322	   322	  if (betraege.some((b) => !/^\d+\.\d{2}$/.test(b) || Number(b) <= 0)) f.push("Betrag nicht im Format 0.00 oder ≤ 0");
323	   323	  const summe = betraege.reduce((a, b) => a + Number(b), 0).toFixed(2);
324	   324	  if (ctrl.some((c) => c !== summe)) f.push("CtrlSum passt nicht zur Summe der Beträge");
325	   325	  for (const m of s.matchAll(/<IBAN>([^<]+)<\/IBAN>/g)) if (!ibanPruefen(m[1])) f.push(`IBAN ungültig: ${m[1].slice(0, 4)}…`);
326	   326	  for (const tag of ["MsgId", "PmtInfId", "EndToEndId"]) for (const m of s.matchAll(new RegExp(`<${tag}>([^<]*)</${tag}>`, "g"))) if (!m[1] || m[1].length > 35) f.push(`${tag} leer oder länger als 35 Zeichen`);
327	   327	  for (const m of s.matchAll(/<(Nm|Ustrd)>([^<]*)<\/\1>/g)) if (/[^A-Za-z0-9/\-?:().,'+ &;]/.test(m[2])) f.push(`Unzulässige Zeichen in ${m[1]}`);
328	   328	  return f;
329	   329	}
