409	   409	/**
410	   410	 * Pflichtangaben einer Rechnung/Gutschrift (§ 14 Abs. 4 UStG DE, § 11 Abs. 1 UStG 1994 AT; Gutschrift § 14 Abs. 2
411	   411	 * UStG bzw. § 11 Abs. 7 UStG 1994) – prüft einen Beleg und liefert fehlende Punkte (leere Liste = vollständig).
412	   412	 */
413	   413	export function pflichtangabenPruefen(beleg) {
414	   414	  const fehlt = [];
415	   415	  const a = beleg.aussteller || {};
416	   416	  const e = beleg.empfaenger || {};
417	   417	  if (!a.name || !a.anschrift) fehlt.push("Name und Anschrift des leistenden Unternehmers");
418	   418	  if (!e.name) fehlt.push("Name des Leistungsempfängers");
419	   419	  if (!e.anschrift) fehlt.push("Anschrift des Leistungsempfängers");
420	   420	  if (!a.uid && !a.steuernummer && beleg.art !== "pacht") fehlt.push("UID bzw. Steuernummer des Ausstellers");
421	   421	  if (!beleg.nummer) fehlt.push("Fortlaufende Rechnungsnummer");
422	   422	  if (!beleg.rechnungsdatum) fehlt.push("Ausstellungsdatum");
423	   423	  if (!beleg.zeitraum?.von || !beleg.zeitraum?.bis) fehlt.push("Leistungszeitraum");
424	   424	  if (!beleg.positionen?.length) fehlt.push("Menge und Art der Leistung");
425	   425	  if (!Number.isFinite(Number(beleg.netto))) fehlt.push("Entgelt (netto)");
426	   426	  if (!beleg.steuer?.vorlage) fehlt.push("Steuersatz bzw. Hinweis auf Steuerbefreiung");
427	   427	  if (beleg.steuer && beleg.steuer.satz === 0 && !beleg.steuer.text) fehlt.push("Hinweis auf Steuerbefreiung / Reverse Charge");
428	   428	  if (beleg.steuer?.art === "reverse_charge" && !e.uid) fehlt.push("UID des Leistungsempfängers (Reverse Charge)");
429	   429	  if (beleg.beleg === "gutschrift" && !/gutschrift/i.test(beleg.titel || "")) fehlt.push("Bezeichnung „Gutschrift“");
430	   430	  // AT: Rechnungen über 10.000 € brutto brauchen die UID des Empfängers (§ 11 Abs. 1 Z 3 lit. i UStG 1994)
431	   431	  if (beleg.aussteller?.land === "AT" && Number(beleg.brutto) > 10000 && beleg.beleg !== "gutschrift" && !e.uid) fehlt.push("UID des Empfängers (AT: Rechnungsbetrag über 10.000 €)");
432	   432	  return fehlt;
433	   433	}
