307	   307	export function provisionNachziehen(db, n, b) {
308	   308	  if (b.art !== "provision") return;
309	   309	  const pv = db.provisionen.find((p) => p.id === b.bezug?.provisionId);
310	   310	  if (!pv || pv.status === "storniert") return;
311	   311	  const ziel = F.provisionStatusAusRechnung(b);
312	   312	  const reihenfolge = ["offen", "in_rechnung", "bezahlt"];
313	   313	  if (reihenfolge.indexOf(ziel) <= reihenfolge.indexOf(pv.status)) return;
314	   314	  const von = pv.status;
315	   315	  pv.status = ziel;
316	   316	  pv.statusVerlauf = pv.statusVerlauf || [];
317	   317	  pv.statusVerlauf.push({ status: ziel, am: jetzt(), vonId: n?.id && n.id !== SYSTEM_FINANZEN.id ? n.id : null, vonRolle: "system", kommentar: ziel === "bezahlt" ? `Zahlung zu Rechnung ${b.nummer} verbucht.` : `Rechnung ${b.nummer} gestellt.` });
318	   318	  pv.rechnung = { id: b.id, nummer: b.nummer, faelligAm: b.faelligAm };
319	   319	  protokoll(db, n?.id === SYSTEM_FINANZEN.id ? null : n, "status", "provision", pv.id, `${von} → ${ziel} (Rechnung ${b.nummer})`);
320	   320	  backofficeEreignis(db, { typ: "status", art: "provision", objekt: pv, von, nach: ziel }); // Automationen
321	   321	}
