335	   335	/**
336	   336	 * Gesperrte Auszahlung sichtbar machen: je Eigentümer und Vertrag ein Klärfall „KYC unvollständig“ (nicht stillschweigend
337	   337	 * überspringen); ist die Freigabe inzwischen erteilt, wird der Klärfall geschlossen.
338	   338	 */
339	   339	export function kycKlaerfall(db, lauf, pt, partei, kyc, trocken = false) {
340	   340	  const schluessel = `KYC:${pt.eigentuemerId}:${pt.id}`;
341	   341	  if (kyc.ok) {
342	   342	    if (!trocken) klaerfallSchliessenKyc(db, schluessel);
343	   343	    return;
344	   344	  }
345	   345	  const e = { art: "pacht", schluessel, bezug: { pachtvertragId: pt.id, kontoId: pt.eigentuemerId }, bezugText: `Auszahlung an ${partei?.name || pt.eigentuemerId} (${pt.bezeichnung})`, gruende: [`KYC unvollständig: ${kyc.gruende.join(" ")}`] };
346	   346	  if (trocken) return;
347	   347	  const vorher = db.finanzen.klaerfaelle.find((k) => k.schluessel === schluessel && k.status === "offen");
348	   348	  if (vorher && vorher.laufId === lauf.id) return;
349	   349	  const { klaerfall, neu } = klaerfallMelden(db, { ...e, laufId: lauf.id });
350	   350	  lauf.klaerfaelle.push({ id: klaerfall.id, art: "pacht", bezugText: e.bezugText, gruende: e.gruende, neu });
351	   351	}
352	   352	
353	   353	export function klaerfallSchliessenKyc(db, schluessel, text = "KYC-Freigabe für Auszahlungen erteilt.") {
354	   354	  for (const k of db.finanzen.klaerfaelle.filter((x) => x.schluessel === schluessel && x.status === "offen")) Object.assign(k, { status: "erledigt", erledigtAm: jetzt(), kommentar: text });
355	   355	}
