357	   357	/**
358	   358	 * Lauf ausführen (innerhalb einer Schreibtransaktion).
359	   359	 * opt: { art: pacht|contracting|provision|alle, stichtag, monat (Contracting), trockenlauf, vertragIds[], anlageIds[], vorab: { anlagen: {id: {anlage, vertrag, messpunkte, zeilen}} }, melden }
360	   360	 */
361	   361	export function laufAusfuehren(db, n, opt) {
362	   362	  const art = opt.art || "alle";
363	   363	  const stichtag = opt.stichtag || F.heute();
364	   364	  const monat = opt.monat || F.vormonat(stichtag.slice(0, 7));
365	   365	  const trocken = !!opt.trockenlauf;
366	   366	  const lauf = { id: trocken ? null : neueId("LA"), art, stichtag, monat, trockenlauf: trocken, am: jetzt(), vonId: n?.id && n.id !== SYSTEM_FINANZEN.id ? n.id : null, vonName: n?.id === SYSTEM_FINANZEN.id ? "Scheduler" : nameVon(db, n?.id) || "", erzeugt: [], klaerfaelle: [], vorhanden: 0, uebersprungen: 0 };
367	   367	  const erzeugen = (e) => {
368	   368	    const b = belegAnlegen(db, n, { ...e, laufId: lauf.id }, { trockenlauf: trocken, melden: opt.melden !== false, heute: opt.rechnungsdatum || F.heute() });
369	   369	    lauf.erzeugt.push({ id: b.id, nummer: b.nummer, art: b.art, empfaenger: b.partei?.name, zeitraum: b.zeitraum, netto: b.netto, brutto: b.brutto, bezugText: b.bezugText });
370	   370	    return b;
371	   371	  };
372	   372	  const klaeren = (e) => {
373	   373	    if (trocken) {
374	   374	      lauf.klaerfaelle.push({ id: null, art: e.art, bezugText: e.bezugText, gruende: e.gruende, neu: true });
375	   375	      return;
376	   376	    }
377	   377	    const { klaerfall, neu } = klaerfallMelden(db, { ...e, laufId: lauf.id });
378	   378	    lauf.klaerfaelle.push({ id: klaerfall.id, art: e.art, bezugText: e.bezugText, gruende: e.gruende, neu });
379	   379	  };
380	   380	  const anlagen = opt.vorab?.anlagen || {};
381	   381	
382	   382	  // ---------------------------------------------------------------- Pacht
383	   383	  if (art === "pacht" || art === "alle") {
384	   384	    for (const pt of db.finanzen.pachtvertraege) {
385	   385	      if (!["aktiv", "gekuendigt"].includes(pt.status)) continue;
386	   386	      if (opt.vertragIds?.length && !opt.vertragIds.includes(pt.id)) continue;
387	   387	      const eigentuemer = nutzerById(db, pt.eigentuemerId);
388	   388	      for (const f of F.abzurechnen(vertragFuerFaelligkeit(db, pt), stichtag)) {
389	   389	        if (aktiverBeleg(db, f.schluessel)) {
390	   390	          lauf.vorhanden++;
391	   391	          continue;
392	   392	        }
393	   393	        const bezugText = `${pt.bezeichnung} (${pt.id}) ${F.datumDe(f.von)} – ${F.datumDe(f.bis)}`;
394	   394	        let ertrag = { kwh: null, fehlt: [] };
395	   395	        if (pt.modell === "umsatz" && f.phase === "pacht") {
396	   396	          const a = anlagen[pt.anlageId];
397	   397	          ertrag = a ? F.ertragAusMonatswerten(a.zeilen, a.messpunkte, f.von, f.bis) : { kwh: null, fehlt: ["keine Anlage/Monatswerte verknüpft"] };
398	   398	        }
399	   399	        const r = F.pachtPositionen(pt, f, { indexTabelle: db.finanzen.vpi, ertragKwh: ertrag.kwh, ertragFehlt: ertrag.fehlt });
400	   400	        if (r.klaerung || !eigentuemer) {
401	   401	          klaeren({ art: "pacht", schluessel: f.schluessel, bezug: { pachtvertragId: pt.id }, bezugText, gruende: [r.klaerung || "Eigentümer-Konto nicht gefunden."] });
402	   402	          continue;
403	   403	        }
404	   404	        if (!(r.netto > 0)) {
405	   405	          lauf.uebersprungen++;
406	   406	          continue;
407	   407	        }
408	   408	        const partei = parteiFuer(db, { kontoId: pt.eigentuemerId });
409	   409	        const kyc = kycAuszahlung(db, { kontoId: pt.eigentuemerId, flaecheId: pt.flaecheId || null });
410	   410	        kycKlaerfall(db, lauf, pt, partei, kyc, trocken);
411	   411	        const pachtGesellschaft = pt.gesellschaftId || (pt.anlageId && anlagen[pt.anlageId] ? anlageGesellschaftId(db, anlagen[pt.anlageId].roh || anlagen[pt.anlageId].anlage) : OEKOINVEST_ID);
412	   412	        erzeugen({
413	   413	          art: "pacht", gesellschaftId: pachtGesellschaft, empfaengerId: pt.eigentuemerId, partei, schluessel: f.schluessel,
414	   414	          bezug: { pachtvertragId: pt.id, flaecheId: pt.flaecheId || null, anlageId: pt.anlageId || null, phase: f.phase },
415	   415	          bezugText, zeitraum: { von: f.von, bis: f.bis }, faelligAm: f.faelligAm, positionen: r.positionen, steuerVorlage: pachtSteuerVorlage(pt),
416	   416	          erklaerung: r.erklaerung, kennzahlen: { ...r.basis, phase: f.phase, zahlweise: f.zahlweise },
417	   417	          hinweise: kyc.ok ? [] : [`Auszahlung gesperrt: ${kyc.gruende.join(" ")}`],
418	   418	        });
419	   419	      }
420	   420	    }
421	   421	  }
422	   422	
423	   423	  // ---------------------------------------------------------------- Contracting (Monat)
424	   424	  if (art === "contracting" || art === "alle") {
425	   425	    const z = F.monatsZeitraum(monat);
426	   426	    for (const [anlageId, a] of Object.entries(anlagen)) {
427	   427	      if (!a.vertrag || a.vertrag.status !== "aktiv") continue;
428	   428	      if (opt.anlageIds?.length && !opt.anlageIds.includes(anlageId)) continue;
429	   429	      if (!a.vertrag.beginn || a.vertrag.beginn > z.bis) continue;
430	   430	      const schluessel = `CV:${anlageId}:${monat}`;
431	   431	      if (aktiverBeleg(db, schluessel)) {
432	   432	        lauf.vorhanden++;
433	   433	        continue;
434	   434	      }
435	   435	      const bezugText = `${a.anlage.name} (${anlageId}) ${monat.slice(5)}/${monat.slice(0, 4)}`;
436	   436	      const r = F.contractingAbrechnen({ vertrag: a.vertrag, anlage: a.anlage, monat, messpunkte: a.messpunkte, zeilen: a.zeilen, indexTabelle: db.finanzen.vpi });
437	   437	      const { kontoId, organisationId } = stromabnehmerVon(a.roh, a.anlage);
438	   438	      const ges = anlageGesellschaft(db, a.roh || a.anlage);
439	   439	      const gesellschaftId = ges.id;
440	   440	      if (r.ok && !ges.bekannt) {
441	   441	        klaeren({ art: "contracting", schluessel, bezug: { anlageId, monat }, bezugText, gruende: [`Eigentümergesellschaft ${gesellschaftId} nicht im Gesellschaftsverzeichnis – Rechnungsaussteller unklar.`] });
442	   442	        continue;
443	   443	      }
444	   444	      if (!r.ok || (!kontoId && !organisationId)) {
445	   445	        klaeren({ art: "contracting", schluessel, bezug: { anlageId, monat }, bezugText, gruende: r.ok ? ["Kein Rechnungsempfänger (Stromabnehmer bzw. Kunde/Organisation) an der Anlage."] : r.klaerung });
446	   446	        continue;
447	   447	      }
448	   448	      erzeugen({
449	   449	        art: "contracting", gesellschaftId, empfaengerId: kontoId, organisationId, partei: parteiFuer(db, { kontoId, organisationId }), schluessel,
450	   450	        bezug: { anlageId, vertragId: a.vertrag.id || null, monat }, bezugText,
451	   451	        zeitraum: z, faelligAm: F.plusTage(opt.rechnungsdatum || F.heute(), einstellungen(db).zahlungszielTage),
452	   452	        positionen: r.positionen, steuerVorlage: a.vertrag.steuervorlage || F.steuerVorschlag("contracting", a.anlage.land).vorlage,
453	   453	        zaehlerstaende: r.zaehlerstaende, hinweise: r.hinweise, kennzahlen: { gelieferteKwh: r.gelieferteKwh, arbeitspreisCt: r.arbeitspreisCt, monat, kwp: a.anlage.kwp },
454	   454	        erklaerung: r.gelieferteKwh !== null ? [`Gelieferter PV-Strom = Erzeugung (geeichter Erzeugungszähler) abzüglich Einspeisung ins Netz. Grundlage: Zählerstand-Monatswerte des Messstellenbetreibers.`] : ["Abrechnung der monatlichen Grundgebühr laut Contracting-Vertrag."],
455	   455	      });
456	   456	    }
457	   457	  }
458	   458	
459	   459	  // ---------------------------------------------------------------- Provision
460	   460	  if (art === "provision" || art === "alle") {
461	   461	    for (const pv of db.provisionen) {
462	   462	      if (!["offen", "in_rechnung"].includes(pv.status)) continue;
463	   463	      const schluessel = `PV:${pv.id}`;
464	   464	      if (aktiverBeleg(db, schluessel)) {
465	   465	        lauf.vorhanden++;
466	   466	        continue;
467	   467	      }
468	   468	      const p = db.projekte.find((x) => x.id === pv.projektId);
469	   469	      const bezugText = `Provision ${pv.id} – ${p?.titel || pv.projektId}`;
470	   470	      if (!nutzerById(db, pv.anbieterId)) {
471	   471	        klaeren({ art: "provision", schluessel, bezug: { provisionId: pv.id }, bezugText, gruende: ["Anbieter-Konto nicht gefunden."] });
472	   472	        continue;
473	   473	      }
474	   474	      const partei = parteiFuer(db, { kontoId: pv.anbieterId, organisationId: p?.organisationId || null });
475	   475	      const land = partei.land || p?.land || "AT";
476	   476	      const vorschlag = F.steuerVorschlag("provision", land, { grundstuecksbezug: true });
477	   477	      const b = erzeugen({
478	   478	        art: "provision", gesellschaftId: OEKOINVEST_ID, empfaengerId: pv.anbieterId, organisationId: p?.organisationId || null, partei, schluessel,
479	   479	        bezug: { provisionId: pv.id, projektId: pv.projektId }, bezugText,
480	   480	        zeitraum: { von: String(pv.erstelltAm).slice(0, 10), bis: String(pv.erstelltAm).slice(0, 10) },
481	   481	        faelligAm: F.plusTage(opt.rechnungsdatum || F.heute(), einstellungen(db).zahlungszielTage),
482	   482	        positionen: F.provisionPositionen(pv, p?.titel || ""), steuerVorlage: vorschlag.vorlage,
483	   483	        hinweise: partei.land ? vorschlag.hinweise : [...vorschlag.hinweise, "Sitz des Anbieters unbekannt – Land des Projekts verwendet."],
484	   484	        erklaerung: [`Provision laut Provisionsvereinbarung: ${F.rund(pv.satz * 100, 2).toLocaleString("de-DE")} % des Kaufpreises, fällig bei Abschluss.`],
485	   485	        kennzahlen: { kaufpreis: pv.kaufpreis, satz: pv.satz },
486	   486	      });
487	   487	      if (!trocken) provisionNachziehen(db, n, b);
488	   488	    }
489	   489	  }
490	   490	
491	   491	  if (!trocken) {
492	   492	    db.finanzen.laeufe.unshift({ ...lauf, erzeugt: lauf.erzeugt.slice(0, 200) });
493	   493	    db.finanzen.laeufe = db.finanzen.laeufe.slice(0, 100);
494	   494	    protokoll(db, n?.id === SYSTEM_FINANZEN.id ? null : n, "abrechnungslauf", "finanzen", lauf.id, `Lauf ${F.LAUF_ARTEN[art]} zum ${F.datumDe(stichtag)}: ${lauf.erzeugt.length} Belege, ${lauf.klaerfaelle.length} Klärfälle`);
495	   495	  }
496	   496	  return lauf;
497	   497	}
