  1	// src/lib/plattform/backend/demo/finanzen.js
  2	//
  3	// Finanzen & Abrechnung im Demo-Backend – Referenz für Frappe plattform/api/finanzen.py (Vertrag: docs/API.md,
  4	// Abschnitt „Finanzen & Abrechnung“). Bildet ab, was im Betrieb ERPNext übernimmt (Purchase Invoice = Pacht-Gutschrift, Sales Invoice =
  5	// Contracting-/Provisionsrechnung, Asset, Project), ohne ERPNext: Belege liegen unter db.finanzen.
