 49	/** Anlagen-Stammdaten + Zählerstand-Monatswerte für Contracting und Umsatzbeteiligung (außerhalb der Schreibsperre laden) */
 50	async function vorabLaden(db, { art = "alle", anlageIds = null, vertragIds = null } = {}) {
 51	  const liste = await anlagenDemo.anlagen(SYSTEM_FINANZEN, {});
 52	  const roh = (await lesen()).anlagen?.anlagen || [];
 53	  const pacht = art === "pacht" || art === "alle";
 54	  const contracting = art === "contracting" || art === "alle";
 55	  const umsatz = new Set(
 56	    pacht ? (db.finanzen?.pachtvertraege || []).filter((p) => p.modell === "umsatz" && p.anlageId && (!vertragIds?.length || vertragIds.includes(p.id))).map((p) => p.anlageId) : []
 57	  );
 58	  const anlagen = {};
 59	  for (const a of liste) {
 60	    const fuerContracting = contracting && !!a.vertrag && (!anlageIds?.length || anlageIds.includes(a.id));
 61	    if (!fuerContracting && !umsatz.has(a.id)) continue;
 62	    try {
 63	      const d = await anlagenDemo.anlage(SYSTEM_FINANZEN, a.id);
 64	      const zeilen = await anlagenDemo.zaehlerMonatswerte(SYSTEM_FINANZEN, a.id);
 65	      anlagen[a.id] = { anlage: { id: d.id, name: d.name, kwp: d.kwp, land: d.land, typ: d.typ, kunde: d.kunde, organisation: d.organisation }, roh: roh.find((x) => x.id === a.id) || null, vertrag: d.vertrag, messpunkte: d.messpunkte, zeilen };
 66	    } catch (e) {
 67	      console.warn("[plattform-finanzen] Anlage", a.id, e?.message);
 68	    }
 69	  }
 70	  return { anlagen };
 71	}
