 73	async function lesenBereit() {
 74	  const db = await lesen();
 75	  if ((db.finanzen?.v || 0) >= FIN_SCHEMA) return db; // nie „zurück“ befüllen (ältere, noch nicht neu übersetzte Module im Dev-Server)
 76	  const vorab = await vorabLaden(db).catch((e) => {
 77	    console.warn("[plattform-finanzen] Anlagen für Demo-Daten nicht geladen:", e?.message);
 78	    return { anlagen: {} };
 79	  });
 80	  await aendern(async (d) => {
 81	    if ((d.finanzen?.v || 0) >= FIN_SCHEMA) return;
 82	    d.finanzen = leer();
 83	    try {
 84	      finanzenSeed(d, { vorab });
 85	    } catch (e) {
 86	      console.warn("[plattform-finanzen] Demo-Daten nicht vollständig ergänzt:", e?.message);
 87	    }
 88	  });
 89	  return lesen();
 90	}
