162	    const r = F.indexiertePacht({ ...pt.index, basisBetrag: pt.pachtJahr, tabelle: db.finanzen.vpi }, jahr);
163	    jahrespacht = r.betrag;
164	    erklaerung = F.indexErklaerung({ ...pt.index, basisBetrag: pt.pachtJahr }, r, F.INDEX_REIHEN[pt.index.reihe]?.label);
165	  } else if (pt.modell === "fest") {
166	    jahrespacht = pt.pachtJahr;
167	    erklaerung = [`Feste Jahrespacht ${F.euro(pt.pachtJahr)} ohne Indexanpassung.`];
168	  } else if (pt.umsatz) {
169	    erklaerung = [`${F.rund(pt.umsatz.anteil * 100, 2).toLocaleString("de-DE")} % der Stromerlöse der Anlage (vereinbarter Erlös ${F.zahlDe(pt.umsatz.erloesCtKwh, 3)} ct/kWh), mindestens ${F.euro(pt.umsatz.mindestJahr)} pro Jahr.`];
170	  }
171	  const nf = F.naechsteFaelligkeit(vf, heute);
172	  let naechste = null;
173	  if (nf) {
174	    const r = F.pachtPositionen(pt, nf, { indexTabelle: db.finanzen.vpi, ertragKwh: pt.modell === "umsatz" ? 0 : null });
175	    naechste = { faelligAm: nf.faelligAm, zeitraum: { von: nf.von, bis: nf.bis }, phase: nf.phase, betrag: r.netto, mindestens: pt.modell === "umsatz" && nf.phase === "pacht" };
176	  }
177	  const ende = F.laufzeitEnde(pt.beginn, pt.laufzeitJahre);
178	  const aus = {
179	    id: pt.id, bezeichnung: pt.bezeichnung, objektArt: pt.objektArt, objektLabel: F.PACHT_OBJEKTE[pt.objektArt] || pt.objektArt, land: pt.land, flaecheHa: pt.flaecheHa,
