181	    pachtJahr: pt.pachtJahr, index: pt.index, umsatz: pt.umsatz, reservierungJahr: pt.reservierungJahr,
182	    vertragsdatum: pt.vertragsdatum, beginnArt: pt.beginnArt, beginnLabel: F.BEGINN_ARTEN[pt.beginnArt] || "", beginn: pt.beginn || "", laufzeitJahre: pt.laufzeitJahre, ende: ende || "",
183	    faelligkeit: pt.faelligkeit, faelligkeitLabel: F.RHYTHMEN[pt.faelligkeit]?.label || "", zahlweise: pt.zahlweise, zahlweiseLabel: F.ZAHLWEISEN[pt.zahlweise] || "", zahlungszielTage: pt.zahlungszielTage,
184	    status: pt.status, statusLabel: F.PACHTVERTRAG_STATUS[pt.status]?.label || pt.status,
185	    jahrespachtAktuell: jahrespacht, erklaerung, naechsteZahlung: naechste,
186	    steuer: { vorlage: pachtSteuerVorlage(pt), label: F.STEUERVORLAGEN[pachtSteuerVorlage(pt)]?.label || "" },
187	  };
188	  if (backoffice) {
189	    const u = nutzerById(db, pt.eigentuemerId);
190	    Object.assign(aus, {
191	      eigentuemerId: pt.eigentuemerId, eigentuemer: u ? { id: u.id, name: nameVon(db, u.id), email: u.email } : null,
192	      gesellschaftId: pt.gesellschaftId || null, gesellschaft: pt.gesellschaftId ? gesellschaftFuer(db, pt.gesellschaftId).name : anlageGesellschaft(db, (db.anlagen?.anlagen || []).find((a) => a.id === pt.anlageId)).name,
193	      steuervorlage: pt.steuervorlage || "", steuerOption: !!pt.steuerOption, kleinunternehmer: !!pt.kleinunternehmer, bemerkung: pt.bemerkung || "",
194	      belege: db.finanzen.belege.filter((b) => b.bezug?.pachtvertragId === pt.id).length,
195	      auszahlung: (() => {
196	        const k = kycAuszahlung(db, { kontoId: pt.eigentuemerId, flaecheId: pt.flaecheId || null });
197	        return { ok: k.ok, gruende: k.gruende, ibanMaskiert: F.ibanMaskieren(k.iban), quelle: k.quelle, kycStatus: k.status };
