207	/** Eigene Abrechnungen mit Jahresübersicht, Verträgen (Indexierung erklärt) und nächster Zahlung */
208	export async function meineAbrechnungen(n, { jahr } = {}) {
209	  angemeldet(n);
210	  let db = await lesenBereit();
211	  if (n.rollen?.includes("anbieter")) db = await provisionenNachziehen(db);
212	  const eigene = db.finanzen.belege.filter((b) => b.status !== "storniert" && (b.empfaengerId === n.id || (b.organisationId && teamRolle(db, n.id, b.organisationId))));
213	  const jahre = [...new Set(eigene.map((b) => Number(String(b.zeitraum?.von || b.rechnungsdatum).slice(0, 4))))].sort((a, b) => b - a);
214	  const aktuell = Number(HEUTE().slice(0, 4));
215	  const j = Number(jahr) && jahre.includes(Number(jahr)) ? Number(jahr) : jahre.includes(aktuell) ? aktuell : jahre[0] || aktuell;
216	  const imJahr = (b) => String(b.zeitraum?.von || "").startsWith(String(j));
217	  const sortiert = (liste) => liste.sort((a, b) => String(b.zeitraum?.von).localeCompare(String(a.zeitraum?.von)) || String(b.nummer).localeCompare(String(a.nummer)));
218	  const summen = (liste) => ({
219	    anzahl: liste.length, netto: F.summe(liste, "netto"), brutto: F.summe(liste, "brutto"),
220	    bezahlt: F.summe(liste.filter((b) => b.status === "bezahlt"), "brutto"), offen: F.summe(liste.filter((b) => ["offen", "angewiesen"].includes(b.status)), "brutto"),
221	  });
222	  const aus = (liste) => sortiert(liste).map((b) => belegAusgabe(db, n, b));
223	
224	  const pacht = eigene.filter((b) => b.art === "pacht");
225	  const vertraege = db.finanzen.pachtvertraege.filter((p) => p.eigentuemerId === n.id && p.status !== "entwurf").map((p) => vertragAusgabe(db, p));
226	  const naechste = vertraege.map((x) => x.naechsteZahlung && { ...x.naechsteZahlung, vertrag: x.bezeichnung }).filter(Boolean).sort((a, b) => a.faelligAm.localeCompare(b.faelligAm))[0] || null;
227	  const kyc = pacht.length || vertraege.length ? kycAuszahlung(db, { kontoId: n.id }) : null;
228	
229	  const contracting = eigene.filter((b) => b.art === "contracting");
230	  const monate = {};
231	  for (const b of contracting.filter(imJahr)) {
232	    const m = b.bezug?.monat || b.zeitraum.von.slice(0, 7);
233	    monate[m] ||= { monat: m, kwh: 0, netto: 0, brutto: 0, anlagen: 0 };
234	    monate[m].kwh += Number(b.kennzahlen?.gelieferteKwh) || 0;
235	    monate[m].netto = F.rund2(monate[m].netto + b.netto);
236	    monate[m].brutto = F.rund2(monate[m].brutto + b.brutto);
237	    monate[m].anlagen += 1;
238	  }
239	  const provision = eigene.filter((b) => b.art === "provision");
240	
241	  return {
242	    jahr: j, jahre: jahre.length ? jahre : [aktuell],
243	    pacht: {
244	      sichtbar: pacht.length > 0 || vertraege.length > 0,
245	      belege: aus(pacht), jahr: summen(pacht.filter(imJahr)), vertraege, naechsteZahlung: naechste,
246	      auszahlung: kyc ? { ok: kyc.ok, ibanMaskiert: F.ibanMaskieren(kyc.iban), hinweis: kyc.ok ? "" : "Auszahlungen erfolgen erst nach abgeschlossener Verifizierung mit geprüfter Bankverbindung." } : null,
247	    },
248	    contracting: { sichtbar: contracting.length > 0, belege: aus(contracting), jahr: summen(contracting.filter(imJahr)), monate: Object.values(monate).sort((a, b) => a.monat.localeCompare(b.monat)) },
249	    provision: { sichtbar: provision.length > 0, belege: aus(provision), jahr: summen(provision.filter(imJahr)) },
250	  };
251	}
