335	/** Zahlungsstatus pflegen: bezahlt | offen | mahnen | storno */
336	export async function abrechnungAktion(n, id, { aktion, datum, grund } = {}) {
337	  schreibNoetig(n);
338	  return aendernBereit((db) => {
339	    const b = db.finanzen.belege.find((x) => x.id === v.kennung(id));
340	    if (!b) throw nichtGefunden("Abrechnung nicht gefunden.");
341	    const heute = HEUTE();
342	    if (aktion === "bezahlt") {
343	      if (!["offen", "angewiesen"].includes(b.status)) throw konflikt("Nur offene Belege können als bezahlt markiert werden.");
344	      if (b.art === "pacht") {
345	        const k = kycAuszahlung(db, { kontoId: b.empfaengerId, flaecheId: b.bezug?.flaecheId || null });
346	        if (!k.ok) throw new PlattformFehler(409, `Keine Auszahlung ohne abgeschlossene Verifizierung: ${k.gruende.join(" ")}`, "kyc");
347	      }
348	      const d = F.istDatum(datum) ? datum : heute;
349	      if (d > heute) throw ungueltig("Das Zahlungsdatum darf nicht in der Zukunft liegen.");
350	      b.status = "bezahlt";
351	      b.bezahltAm = d;
352	      provisionNachziehen(db, n, b);
353	      belegMelden(db, b, "bezahlt");
354	    } else if (aktion === "offen") {
355	      if (b.status !== "angewiesen") throw konflikt("Nur angewiesene Zahlungen können zurückgesetzt werden.");
356	      b.status = "offen";
357	      b.zahlungslaufId = null;
358	    } else if (aktion === "mahnen") {
359	      if (b.beleg !== "rechnung" || F.zahlungsstatus(b, heute) !== "ueberfaellig") throw konflikt("Erinnern nur bei überfälligen Rechnungen.");
360	      const h = F.mahnhinweis(b, heute);
361	      b.mahnungen = [...(b.mahnungen || []), { am: jetzt(), stufe: Math.max(1, h?.stufe || 1), label: h?.label || "Zahlungserinnerung", vonId: n.id }];
362	      belegMelden(db, b, "erinnerung");
363	    } else if (aktion === "storno") {
364	      const g = v.mehrzeilig(grund, 500);
365	      if (g.length < 5) throw ungueltig("Bitte geben Sie einen Grund für die Stornierung an (mind. 5 Zeichen).");
366	      if (!["offen"].includes(b.status)) throw konflikt("Nur offene Belege können storniert werden (bezahlte/angewiesene zuerst zurücksetzen bzw. Gutschrift korrigieren).");
367	      b.status = "storniert";
368	      b.stornoGrund = g;
