143	   143	/** Operative Jahreswerte P50 und P90 (Index 0 = Jahr 1) */
144	   144	export function betriebsJahre(e) {
145	   145	  const kwp = e.mwp * 1000;
146	   146	  const jahre = [];
147	   147	  const vertrag = e.modell === "merchant" ? 0 : Math.min(e.vertragJahre, e.laufzeit);
148	   148	  for (let t = 1; t <= e.laufzeit; t++) {
149	   149	    const deg = Math.pow(1 - FREIFLAECHE.degradation, t - 1);
150	   150	    const marktCt = e.merchantCt * Math.pow(1 + ERLOESE.merchantSteigerung, t - 1);
151	   151	    const imVertrag = t <= vertrag;
152	   152	    let preisCt;
153	   153	    if (!imVertrag) preisCt = marktCt;
154	   154	    else if (e.modell === "eeg") preisCt = Math.max(e.preisCt, marktCt);
155	   155	    else if (e.modell === "contracting") {
156	   156	      const liefer = e.preisCt * Math.pow(1 + (e.indexierung || 0), t - 1);
157	   157	      preisCt = (e.lieferAnteil ?? 1) * liefer + (1 - (e.lieferAnteil ?? 1)) * marktCt;
158	   158	    } else preisCt = e.preisCt * Math.pow(1 + (e.indexierung || 0), t - 1);
159	   159	    const e50 = kwp * e.p50 * deg;
160	   160	    const e90 = kwp * e.p90 * deg;
161	   161	    const opex = kwp * e.opexKwp * Math.pow(1 + FREIFLAECHE.inflation, t - 1);
162	   162	    const pacht = e.pachtJahr * Math.pow(1 + PACHT.indexierung, t - 1);
163	   163	    const rueckbau = (kwp * FREIFLAECHE.rueckbauProKwp) / e.laufzeit;
164	   164	    const kosten = opex + pacht + rueckbau;
165	   165	    const erloes50 = (e50 * preisCt) / 100;
166	   166	    const erloes90 = (e90 * preisCt) / 100;
167	   167	    jahre.push({ jahr: t, preisCt, imVertrag, erzeugung50: e50, erzeugung90: e90, erloes50, erloes90, opex, pacht, rueckbau, kosten, cfads50: erloes50 - kosten, cfads90: erloes90 - kosten });
168	   168	  }
169	   169	  return jahre;
170	   170	}
