174	   174	/**
175	   175	 * Tilgungsplan über T Jahre (Arrays Länge T, Index 0 = Jahr 1).
176	   176	 * profil: annuitaet | linear | endfaellig | skulptiert (dienst = Schuldendienst je Jahr vorgegeben)
177	   177	 */
178	   178	export function tilgungsplan({ betrag, zins, jahre, profil = "annuitaet", anlauf = 0, dienst = null, T = jahre }) {
179	   179	  const zinsen = new Array(T).fill(0);
180	   180	  const tilgung = new Array(T).fill(0);
181	   181	  const rest = new Array(T).fill(0);
182	   182	  let r = Math.max(0, betrag);
183	   183	  const n = Math.max(1, Math.min(jahre, T));
184	   184	  const a = Math.min(anlauf, n - 1);
185	   185	  const rate = profil === "annuitaet" ? annuitaet(r, zins, n - a) : 0;
186	   186	  for (let t = 1; t <= T; t++) {
187	   187	    const i = t - 1;
188	   188	    if (r <= 0.005 || t > n) {
189	   189	      rest[i] = Math.max(r, 0);
190	   190	      continue;
191	   191	    }
192	   192	    zinsen[i] = r * zins;
193	   193	    let tg = 0;
194	   194	    if (t <= a) tg = 0;
195	   195	    else if (profil === "annuitaet") tg = rate - zinsen[i];
196	   196	    else if (profil === "linear") tg = betrag / (n - a);
197	   197	    else if (profil === "endfaellig") tg = t === n ? r : 0;
198	   198	    else if (profil === "skulptiert") tg = (dienst?.[i] || 0) - zinsen[i];
199	   199	    if (t === n) tg = r; // Restschuld im letzten Jahr vollständig
200	   200	    tg = Math.min(tg, r);
201	   201	    tilgung[i] = tg;
202	   202	    r -= tg;
203	   203	    rest[i] = Math.max(r, 0);
204	   204	  }
205	   205	  return { zinsen, tilgung, rest, dienst: zinsen.map((z, i) => z + tilgung[i]) };
206	   206	}
