208	   208	/**
209	   209	 * DSCR-Skulptierung: Schuldendienst_t = CFADS_t ÷ Ziel-DSCR über den Tenor; Darlehen = Barwert dieses Schuldendienstes zum
210	   210	 * Kreditzins (so ist die Restschuld am Laufzeitende genau null). Obergrenze fkMax × Investition (dann proportional gekürzt).
211	   211	 */
212	   212	export function skulptieren({ cfads, zins, jahre, dscrZiel, maxBetrag = Infinity }) {
213	   213	  const n = Math.min(jahre, cfads.length);
214	   214	  const ds = cfads.slice(0, n).map((c) => Math.max(0, c) / dscrZiel);
215	   215	  const bw = ds.reduce((s, d, i) => s + d / Math.pow(1 + zins, i + 1), 0);
216	   216	  const faktor = bw > maxBetrag ? maxBetrag / bw : 1;
217	   217	  return { betrag: bw * faktor, dienst: ds.map((d) => d * faktor), begrenzt: faktor < 1, faktor };
218	   218	}
