222	   222	/** AfA-Reihe (Länge T): linear bzw. degressiv mit Wechsel zur linearen AfA, ab Jahr `start` (1-basiert) */
223	   223	export function afaReihe(basis, jahre, T, { degressivSatz = 0, start = 1 } = {}) {
224	   224	  const out = new Array(T).fill(0);
225	   225	  let rest = basis;
226	   226	  for (let t = start; t <= T && rest > 0.5; t++) {
227	   227	    const verbleibend = Math.max(1, jahre - (t - start));
228	   228	    const linear = rest / verbleibend;
229	   229	    const deg = degressivSatz > 0 ? rest * Math.min(degressivSatz, 3 / jahre) : 0;
230	   230	    const a = Math.min(rest, Math.max(linear, deg));
231	   231	    out[t - 1] = a;
232	   232	    rest -= a;
233	   233	  }
234	   234	  return out;
235	   235	}
