432	   432	  const cf90 = [-e.capex, ...jahre.map((j) => j.cfads90)];
433	   433	  const wacc = e.fkQuote * e.zins + (1 - e.fkQuote) * e.diskontEk;
434	   434	  const bwKosten = e.capex + jahre.reduce((s, j) => s + j.kosten / Math.pow(1 + wacc, j.jahr), 0);
435	   435	  const bwEnergie = jahre.reduce((s, j) => s + j.erzeugung50 / Math.pow(1 + wacc, j.jahr), 0);
