437	   437	    projektIrr: irr(cf),
438	   438	    projektIrrP90: irr(cf90),
439	   439	    npv: npv(wacc, cf),
440	   440	    wacc,
441	   441	    amortisation: amortisation(cf),
442	   442	    lcoeCt: bwEnergie > 0 ? (bwKosten / bwEnergie) * 100 : null,
443	   443	    roi: (summe(cf.slice(1)) - e.capex) / e.capex,
444	   444	    ertragJahr1Mwh: (jahre[0]?.erzeugung50 || 0) / 1000,
445	   445	    erloesJahr1: jahre[0]?.erloes50 || 0,
446	   446	    cfadsJahr1: jahre[0]?.cfads50 || 0,
447	   447	    capexProKwp: e.capex / (e.mwp * 1000),
448	   448	  };
