 84	const z = (v, min, max, stellen = 4) => {
 85	  if (v === null || v === undefined || v === "") return null;
 86	  const n = typeof v === "number" ? v : Number(String(v ?? "").replace(",", "."));
 87	  if (!Number.isFinite(n)) return null;
 88	  const f = Math.pow(10, stellen);
 89	  return Math.round(Math.min(max, Math.max(min, n)) * f) / f;
 90	};
 91	const txt = (v, max = 500) => String(v ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "").trim().slice(0, max);
