 93	/** Term Sheet bereinigen und prüfen (Werte in Prozent als Prozentzahl, z. B. 1,8 = 1,8 %) */
 94	export function termsheetBereinigen(d = {}) {
 95	  const t = {
 96	    betrag: z(d.betrag, 0, 5e9, 0),
 97	    laufzeitJahre: z(d.laufzeitJahre, 1, 35, 0),
 98	    zinsArt: REFERENZZINSEN[d.zinsArt] ? d.zinsArt : "fix",
 99	    zinsPct: z(d.zinsPct, 0, 20),
100	    referenzAnnahmePct: z(d.referenzAnnahmePct, -1, 15) ?? P.referenzzinsPct,
101	    margePct: z(d.margePct, 0, 10),
102	    tilgungsprofil: TILGUNG_PROFILE[d.tilgungsprofil] ? d.tilgungsprofil : "annuitaet",
103	    tilgungsfreiJahre: z(d.tilgungsfreiJahre, 0, 5, 0) ?? 0,
104	    dscrSizing: z(d.dscrSizing, 1, 3, 3),
105	    dscrCovenant: z(d.dscrCovenant, 1, 3, 3) ?? P.dscrDefault,
106	    dscrLockup: z(d.dscrLockup, 1, 3, 3) ?? P.dscrLockup,
107	    llcrCovenant: z(d.llcrCovenant, 1, 3, 3),
108	    dsraMonate: z(d.dsraMonate, 0, 24, 0) ?? P.dsraMonate,
109	    bearbeitungPct: z(d.bearbeitungPct, 0, 10) ?? 0,
110	    bereitstellungPct: z(d.bereitstellungPct, 0, 5) ?? 0,
111	    sicherheiten: (Array.isArray(d.sicherheiten) ? d.sicherheiten : []).filter((s) => SICHERHEITEN[s]).slice(0, 10),
112	    cps: (Array.isArray(d.cps) ? d.cps : []).filter((c) => CP_STANDARD.some((x) => x.id === c)).slice(0, 20),
113	    gueltigBis: /^\d{4}-\d{2}-\d{2}$/.test(String(d.gueltigBis || "")) ? d.gueltigBis : "",
114	    bemerkung: txt(d.bemerkung, 1500),
115	  };
116	  pflicht(t.betrag > 0, "Bitte den Kreditbetrag angeben.");
117	  pflicht(t.laufzeitJahre, "Bitte die Laufzeit angeben.");
118	  if (t.zinsArt === "fix") pflicht(t.zinsPct !== null, "Bitte den Festzins angeben.");
119	  else pflicht(t.margePct !== null, "Bitte die Marge über dem Referenzzins angeben.");
120	  pflicht(t.dscrLockup >= t.dscrCovenant, "Der Lock-up-DSCR muss mindestens so hoch sein wie der Covenant-DSCR.");
121	  return t;
122	}
