124	/** All-in-Zins (Anteil) eines Term Sheets: Festzins bzw. angenommener Referenzzins + Marge */
125	export const allInZins = (t) => (t.zinsArt === "fix" ? t.zinsPct : (t.referenzAnnahmePct || 0) + (t.margePct || 0)) / 100;
