127	/**
128	 * Kennzahlen eines Term Sheets gegen das Financial Model (Cockpit-Eingaben e): Schuldendienst nach Tilgungsprofil,
129	 * DSCR P50/P90, LLCR, EK-Bedarf, EK-IRR, Finanzierungskosten, Effektivkosten p. a. (IRR der Bank-Zahlungsreihe), Covenant-Puffer.
130	 */
131	export function termsheetKennzahlen(t, e) {
132	  const jahre = betriebsJahre(e);
133	  const T = jahre.length;
134	  const zins = allInZins(t);
135	  const betrag = Math.min(t.betrag, e.capex);
136	  let dienstVorgabe = null;
137	  if (t.tilgungsprofil === "skulptiert") {
138	    const s = skulptieren({ cfads: jahre.map((j) => j.cfads90), zins, jahre: t.laufzeitJahre, dscrZiel: t.dscrSizing || P.dscrP90 });
139	    dienstVorgabe = s.dienst.map((d) => (d * betrag) / Math.max(s.betrag, 1));
140	  }
141	  const plan = tilgungsplan({ betrag, zins, jahre: t.laufzeitJahre, profil: t.tilgungsprofil, anlauf: t.tilgungsfreiJahre, dienst: dienstVorgabe, T });
142	  const gebuehr = (betrag * (t.bearbeitungPct || 0)) / 100;
143	  const erst = plan.dienst.find((d) => d > 0.5) || 0;
144	  const dsra = (erst * (t.dsraMonate || 0)) / 12;
145	  const ende = Math.min(t.laufzeitJahre, T);
146	  const ek0 = e.capex - betrag + gebuehr + dsra;
147	  const cfEk = [-ek0, ...jahre.map((j, i) => j.cfads50 - plan.dienst[i] + (i === ende - 1 ? dsra : 0))];
148	  const d50 = [];
149	  const d90 = [];
150	  jahre.forEach((j, i) => {
151	    if (plan.dienst[i] > 0.5) {
152	      d50.push(j.cfads50 / plan.dienst[i]);
153	      d90.push(j.cfads90 / plan.dienst[i]);
154	    }
155	  });
156	  const bank = [-(betrag - gebuehr), ...plan.dienst.slice(0, ende)];
157	  const llcr = betrag > 0 ? (npv(zins, [0, ...jahre.slice(0, ende).map((j) => j.cfads90)]) + dsra) / betrag : null;
158	  const dscrMinP90 = d90.length ? Math.min(...d90) : null;
159	  return {
160	    zinsAllIn: zins,
161	    betrag,
162	    fkQuote: betrag / e.capex,
163	    kapitalbedarfEk: ek0,
164	    gebuehr,
165	    dsra,
166	    rateJahr1: plan.dienst[0],
167	    dscrMin: d50.length ? Math.min(...d50) : null,
168	    dscrMittel: d50.length ? d50.reduce((s, x) => s + x, 0) / d50.length : null,
169	    dscrMinP90,
170	    llcr,
171	    ekIrr: ek0 > 0 ? irr(cfEk) : null,
172	    zinsenSumme: plan.zinsen.reduce((s, x) => s + x, 0),
173	    kostenSumme: plan.zinsen.reduce((s, x) => s + x, 0) + gebuehr,
174	    effektivPa: irr(bank),
175	    covenantPuffer: dscrMinP90 !== null ? dscrMinP90 - t.dscrCovenant : null,
176	    covenantHaltbar: dscrMinP90 === null ? true : dscrMinP90 >= t.dscrCovenant,
177	    plan,
178	  };
179	}
