181	/** Vergleich mehrerer Term Sheets: Kennzahlen + Rangfolge (EK-IRR, bei Covenant-Risiko abgewertet) + Empfehlungstext */
182	export function termsheetVergleich(liste = [], e) {
183	  const zeilen = liste.map((x) => ({ ...x, k: termsheetKennzahlen(x.termsheet, e) }));
184	  const wert = (r) => (r.k.ekIrr ?? -1) - (r.k.covenantHaltbar ? 0 : 1);
185	  const sortiert = [...zeilen].sort((a, b) => wert(b) - wert(a));
186	  sortiert.forEach((r, i) => (r.rang = i + 1));
187	  const beste = sortiert[0];
188	  const empfehlung = beste
189	    ? `${beste.bank || "Angebot 1"}: höchste Eigenkapitalrendite${beste.k.covenantHaltbar ? " bei eingehaltenem DSCR-Covenant im P90-Fall" : " – Achtung: DSCR-Covenant im P90-Fall nicht eingehalten"}. Entscheidung trifft die Leitung nach Prüfung der Sicherheiten und Auszahlungsvoraussetzungen.`
190	    : "";
191	  return { zeilen: sortiert.map(({ k: { plan: _p, ...k }, ...r }) => ({ ...r, k })), empfehlung };
192	}
