204	/**
205	 * Ampel eines Prüftermins. dscr: gemessener DSCR (rollierende 12 Monate); vorher: DSCR des Vortermins (Trend).
206	 * rot  < Lock-up (Ausschüttungssperre) – „verletzt“ zusätzlich, wenn < Covenant (Default)
207	 * gelb < Lock-up + Puffer oder deutlich fallender Trend (> 0,1 gegenüber Vortermin)
208	 */
209	export function covenantAmpel({ dscr, lockup = P.dscrLockup, covenant = P.dscrDefault, vorher = null }) {
210	  if (dscr === null || dscr === undefined || !Number.isFinite(dscr)) return { id: "grau", verletzt: false, lockup: false, grund: "Keine Messdaten bzw. kein Schuldendienst im Zeitraum." };
211	  if (dscr < covenant) return { id: "rot", verletzt: true, lockup: true, grund: `DSCR ${dscr.toFixed(2).replace(".", ",")} unter dem Covenant ${covenant.toFixed(2).replace(".", ",")} – Kündigungsrecht der Bank (Event of Default), sofort mit der Bank sprechen.` };
212	  if (dscr < lockup) return { id: "rot", verletzt: false, lockup: true, grund: `DSCR ${dscr.toFixed(2).replace(".", ",")} unter dem Lock-up ${lockup.toFixed(2).replace(".", ",")} – Ausschüttungssperre.` };
213	  if (dscr < lockup + FRUEHWARN_PUFFER) return { id: "gelb", verletzt: false, lockup: false, grund: `DSCR ${dscr.toFixed(2).replace(".", ",")} nur knapp über dem Lock-up ${lockup.toFixed(2).replace(".", ",")}.` };
214	  if (vorher !== null && Number.isFinite(vorher) && vorher - dscr > 0.1) return { id: "gelb", verletzt: false, lockup: false, grund: `DSCR fällt deutlich (${vorher.toFixed(2).replace(".", ",")} → ${dscr.toFixed(2).replace(".", ",")}).` };
215	  return { id: "gruen", verletzt: false, lockup: false, grund: `DSCR ${dscr.toFixed(2).replace(".", ",")} – ausreichend Abstand zum Lock-up.` };
216	}
