218	/**
219	 * Covenant-Prüfung aus Monatswerten: je Quartalsende DSCR der letzten 12 Monate (LTM) = CFADS ÷ Schuldendienst.
220	 * monate: [{ monat: "JJJJ-MM", cfads, schuldendienst, quelle }] (aufsteigend). LLCR zum Stichtag: Barwert der
221	 * geplanten CFADS über die Restlaufzeit (planCfads je Folgejahr) ÷ Restschuld.
222	 */
223	export function covenantPruefung({ monate = [], lockup, covenant, llcrCovenant = null, restschuld = 0, planCfads = [], zins = 0.045 } = {}) {
224	  const sortiert = [...monate].sort((a, b) => a.monat.localeCompare(b.monat));
225	  const pruefungen = [];
226	  for (let i = 11; i < sortiert.length; i++) {
227	    const m = sortiert[i].monat;
228	    const quartalsende = ["03", "06", "09", "12"].includes(m.slice(5, 7));
229	    if (!quartalsende && i !== sortiert.length - 1) continue; // Prüftermine: Quartalsenden + laufender Stand (letzter vollständiger Monat)
230	    const fenster = sortiert.slice(i - 11, i + 1);
231	    const cfads = fenster.reduce((s, x) => s + (x.cfads || 0), 0);
232	    const ds = fenster.reduce((s, x) => s + (x.schuldendienst || 0), 0);
233	    const dscr = ds > 0.5 ? cfads / ds : null;
234	    const vorher = pruefungen.length ? pruefungen[pruefungen.length - 1].dscr : null;
235	    const quartal = quartalsende ? `Q${Math.ceil(Number(m.slice(5, 7)) / 3)}/${m.slice(0, 4)}` : `LTM bis ${m.slice(5, 7)}/${m.slice(0, 4)}`;
236	    pruefungen.push({ periode: quartal, bis: m, laufend: !quartalsende, cfads, schuldendienst: ds, dscr, prognoseAnteil: fenster.filter((x) => x.quelle === "prognose").length / 12, ampel: covenantAmpel({ dscr, lockup, covenant, vorher }) });
237	  }
238	  const llcr = restschuld > 0.5 && planCfads.length ? npv(zins, [0, ...planCfads]) / restschuld : null;
239	  const letzte = pruefungen[pruefungen.length - 1] || null;
240	  let ampel = letzte ? letzte.ampel : covenantAmpel({ dscr: null });
241	  if (llcr !== null && llcrCovenant && llcr < llcrCovenant && ampel.id !== "rot") ampel = { id: "rot", verletzt: true, lockup: true, grund: `LLCR ${llcr.toFixed(2).replace(".", ",")} unter dem Covenant ${llcrCovenant.toFixed(2).replace(".", ",")}.` };
242	  return { pruefungen, llcr, ampel, letzte };
243	}
