147	//
148	// Geschäftsmodell je Entwicklungsprojekt – Entscheidungsgrundlage für die Geschäftsführung (reine Logik):
149	//   verkauf      Build-to-Sell: Projektrechte/SPV verkaufen, ÖKOVOLT baut für den Investor (EPC) – Erlös heute
150	//   eigenbetrieb ÖkoInvest bzw. SPV betreibt selbst mit Bankfinanzierung – Barwert der Eigenkapital-Cashflows
151	//   contracting  Anlage im Eigentum, Strom an Kunden vor Ort (Dach-/Direktlieferung) – Barwert nach Finanzierung
152	//   verpachtung  Flächen-/Dachrechte an einen Betreiber weitergeben – Barwert des Nutzungsentgelts abzüglich eigener Pacht
153	// Vergleichsmaß: Barwert zum Eigenkapital-Diskontsatz (heutiger Wert) – dazu Kapitalbindung und Risiken.
154	// Orientierung, keine Beratung. Konzernsicht (EPC-Marge ÖKOVOLT) nur auf Wunsch einrechnen.
155	
156	import { DACH, PACHT, PHASEN, npv } from "../../invest/markt.js";
157	import { cockpitBereinigen, varianteRechnen, betriebsJahre, VARIANTEN } from "./kern.js";
