161	  eigenbetrieb: { label: "Eigenbetrieb mit Bankfinanzierung", kurz: "Eigenbetrieb" },
162	  contracting: { label: "Contracting im Eigentum (Direktlieferung)", kurz: "Contracting" },
163	  verpachtung: { label: "Reine Verpachtung an Betreiber", kurz: "Verpachtung" },
