167	const rtb = PHASEN.find((p) => p.id === "rtb");
168	
169	/** Standardannahmen für den Vergleich (überschreibbar) */
170	export function modellStandard(e) {
171	  return {
172	    verkaufspreisKwp: Math.round((rtb.preisProKwp.min + rtb.preisProKwp.max) / 2),
173	    epcMargePct: 0,
174	    finanzierung: "skulptiert",
175	    lieferpreisCt: DACH.ppaVorOrtCt.mittel,
176	    lieferAnteil: DACH.eigenverbrauch.standard,
177	    nutzungsentgeltJahr: Math.round((e?.mwp || 10) * 1.1 * PACHT.freiflaecheProHa.max),
178	  };
179	}
180	
181	const zahl = (v, min, max, std) => {
182	  const n = Number(String(v ?? "").replace(",", "."));
183	  return v === "" || v === null || v === undefined || !Number.isFinite(n) ? std : Math.min(max, Math.max(min, n));
184	};
