186	/** Vergleich aller Geschäftsmodelle. eingaben: Cockpit-Eingaben; annahmen: siehe modellStandard */
187	export function geschaeftsmodellVergleich(eingaben = {}, annahmen = {}) {
188	  const e = cockpitBereinigen(eingaben);
189	  const s = modellStandard(e);
190	  const a = {
191	    verkaufspreisKwp: zahl(annahmen.verkaufspreisKwp, 0, 1500, s.verkaufspreisKwp),
192	    epcMargePct: zahl(annahmen.epcMargePct, 0, 30, s.epcMargePct),
193	    finanzierung: VARIANTEN[annahmen.finanzierung] ? annahmen.finanzierung : s.finanzierung,
194	    lieferpreisCt: zahl(annahmen.lieferpreisCt, 0, 60, s.lieferpreisCt),
195	    lieferAnteil: zahl(annahmen.lieferAnteil, 0, 1, s.lieferAnteil),
196	    nutzungsentgeltJahr: zahl(annahmen.nutzungsentgeltJahr, 0, 5e7, s.nutzungsentgeltJahr),
197	  };
198	  const kwp = e.mwp * 1000;
199	  const epcMarge = (e.capex * a.epcMargePct) / 100;
200	
201	  const verkaufErloes = a.verkaufspreisKwp * kwp;
202	  const eigen = varianteRechnen(a.finanzierung, e);
203	  const eC = { ...e, modell: "contracting", preisCt: a.lieferpreisCt, lieferAnteil: a.lieferAnteil, indexierung: 0.015, vertragJahre: Math.min(20, e.laufzeit) };
204	  const contr = varianteRechnen(a.finanzierung, eC);
205	  const netto = [];
206	  for (let t = 1; t <= e.laufzeit; t++) netto.push((a.nutzungsentgeltJahr - e.pachtJahr) * Math.pow(1 + PACHT.indexierung, t - 1));
207	  const verpachtungBw = npv(e.diskontEk, [0, ...netto]);
