223	      dscrMin: contr.dscrMin, fremdkapital: contr.fremdkapital,
224	      vorteile: ["Höherer Erlös je kWh durch Direktlieferung", "Langfristige Kundenbindung"],
225	      risiken: ["Bonität des Abnehmers (Ausfall/Insolvenz)", "Dienstbarkeit/Dachvertrag nötig, Abnahmemenge schwankt"],
226	    },
227	    {
228	      id: "verpachtung", ...GESCHAEFTSMODELLE.verpachtung, heute: 0, barwert: verpachtungBw, kapitalbindung: 0, irr: null,
229	      vorteile: ["Kein Kapitaleinsatz, planbare Einnahmen", "Geringer Aufwand"],
230	      risiken: ["Niedrigster Wert, Betreiberbonität", "Nutzungsentgelt hängt von der Verhandlung ab (Annahme)"],
231	    },
232	  ];
233	  const beste = [...zeilen].sort((x, y) => y.barwert - x.barwert)[0];
234	  const verkaufZeile = zeilen[0];
235	  const empfehlung = `${beste.label} hat mit rund ${Math.round(beste.barwert / 1000).toLocaleString("de-DE")} T€ den höchsten Barwert${beste.kapitalbindung > 0 ? ` bei ${Math.round(beste.kapitalbindung / 1000).toLocaleString("de-DE")} T€ Eigenkapitalbindung` : ""}. ` +
