256	  const typ = TYPEN_FZ[p.typ] ? p.typ : "freiflaeche";
257	  const inv = vb.modus === "entwicklung" ? investition({ mwp: b.mwp, capexKwp: b.capexKwp, entwicklungKwp: (b.kaufpreisKwp || 0) + (b.restentwicklungKwp || 0), netzKm: b.netzKm }) : null;
