    43	function fallAnreichern(f) {
    44	  if (!f?.eingaben) return f;
    45	  const e = cockpitBereinigen(f.eingaben);
    46	  const mitTs = (f.anfragen || []).filter((a) => a.termsheet);
    47	  let vergleich = { zeilen: [], empfehlung: "" };
    48	  try {
    49	    if (mitTs.length) vergleich = termsheetVergleich(mitTs.map((a) => ({ anfrageId: a.id, bank: a.bank, termsheet: a.termsheet.daten })), e);
    50	  } catch {
    51	    /* unvollständiges Term Sheet – Vergleich bleibt leer */
    52	  }
    53	  const c = rechneCockpit(e, { varianten: ["ek", "annuitaet", "skulptiert", "foerder", "misch"] });
    54	  return { ...f, eingaben: e, vergleich, modell: { projekt: c.projekt, varianten: c.varianten.map(({ reihen: _r, ...x }) => x) } };
    55	}
