 64	const rund = (x, s = 2) => (Number.isFinite(x) ? Math.round(x * 10 ** s) / 10 ** s : null);
 65	const zahl = (v, min, max, stellen = 3) => {
 66	  if (v === undefined || v === null || v === "" || typeof v === "object" || typeof v === "boolean") return null;
 67	  const n = typeof v === "number" ? v : Number(String(v).replace(/\s/g, "").replace(",", "."));
