 84	export function produkteBereinigen(liste = []) {
 85	  const out = [];
 86	  for (const p of Array.isArray(liste) ? liste.slice(0, 8) : []) {
 87	    const art = Object.prototype.hasOwnProperty.call(PRODUKT_ARTEN, p?.art) ? p.art : null;
 88	    if (!art) continue;
 89	    const laufzeitJahre = LAUFZEITEN.includes(Number(p.laufzeitJahre)) ? Number(p.laufzeitJahre) : 1;
 90	    const tranchen = art === "tranchen" ? Math.min(24, Math.max(2, Math.round(Number(p.tranchen) || 4))) : null;
 91	    out.push({ id: `P${out.length + 1}`, art, laufzeitJahre, tranchen, gruen: p.gruen === true || p.gruen === "ja" });
 92	  }
 93	  if (!out.length) throw new Ungueltig("Bitte mindestens eine Produktvariante wählen (Festpreis, Tranchen oder Spot-Index).");
 94	  return out;
 95	}
