100	  return `${a}${p.art === "tranchen" && p.tranchen ? ` (${p.tranchen} Tranchen)` : ""}, ${p.laufzeitJahre} ${p.laufzeitJahre === 1 ? "Jahr" : "Jahre"}${p.gruen ? ", Grünstrom (HKN)" : ""}`;
