103	/**
104	 * Preisblatt eines Lieferanten prüfen. Pflicht je angebotener Position: Arbeitspreis (Festpreis) bzw. Aufschlag
105	 * (Tranchen/Spot), Grundpreis, bei Grünstrom HKN-Aufschlag; für das ganze Angebot: Bindefrist (nach Angebotsfrist),
106	 * Zahlungsziel, Sicherheit. Mindestens eine Position.
107	 * @param {object} eingabe {positionen: [{produktId, arbeitspreisCt?, aufschlagCt?, grundpreisEurMonat, hknCt?, mengentoleranzProzent?}], bindefristBis, zahlungszielTage, sicherheit, bemerkung}
108	 * @param {object[]} produkte bereinigte Produktvarianten der Ausschreibung
109	 * @param {{frist: ISO}} runde aktuelle Runde (Bindefrist muss danach liegen)
110	 */
111	export function preisblattPruefen(eingabe = {}, produkte = [], { frist } = {}) {
112	  const positionen = [];
113	  const gesehen = new Set();
114	  for (const x of Array.isArray(eingabe.positionen) ? eingabe.positionen.slice(0, 8) : []) {
115	    const p = produkte.find((y) => y.id === x?.produktId);
116	    if (!p || gesehen.has(p.id)) continue;
117	    gesehen.add(p.id);
118	    const pos = { produktId: p.id, art: p.art, arbeitspreisCt: null, aufschlagCt: null, grundpreisEurMonat: zahl(x.grundpreisEurMonat, 0, 100000, 2), hknCt: null, mengentoleranzProzent: zahl(x.mengentoleranzProzent, 0, 100, 1) };
119	    if (p.art === "fix") {
120	      pos.arbeitspreisCt = zahl(x.arbeitspreisCt, 0.5, 100);
121	      if (pos.arbeitspreisCt === null) throw new Ungueltig(`${produktLabel(p)}: Arbeitspreis in ct/kWh fehlt oder ist unplausibel (0,5–100).`);
122	    } else {
123	      pos.aufschlagCt = zahl(x.aufschlagCt, -5, 20);
124	      if (pos.aufschlagCt === null) throw new Ungueltig(`${produktLabel(p)}: Aufschlag in ct/kWh fehlt oder ist unplausibel (−5 bis 20).`);
125	    }
126	    if (pos.grundpreisEurMonat === null) throw new Ungueltig(`${produktLabel(p)}: Grundpreis in €/Monat fehlt (0 ist zulässig).`);
127	    if (p.gruen) {
128	      pos.hknCt = zahl(x.hknCt, 0, 10);
129	      if (pos.hknCt === null) throw new Ungueltig(`${produktLabel(p)}: Aufschlag für Herkunftsnachweise fehlt (0 ist zulässig).`);
130	    }
131	    positionen.push(pos);
132	  }
133	  if (!positionen.length) throw new Ungueltig("Bitte mindestens eine Produktvariante bepreisen.");
134	  const bindefristBis = text(eingabe.bindefristBis, 30);
135	  const bf = Date.parse(bindefristBis);
136	  if (!bindefristBis || !Number.isFinite(bf)) throw new Ungueltig("Bitte eine Bindefrist (Datum und Uhrzeit) angeben.");
137	  if (frist && bf < Date.parse(frist) + 3600e3) throw new Ungueltig("Die Bindefrist muss mindestens eine Stunde nach der Angebotsfrist liegen (Zeit für Auswertung und Kundenfreigabe).");
138	  const zahlungszielTage = zahl(eingabe.zahlungszielTage, 0, 90, 0);
139	  if (zahlungszielTage === null) throw new Ungueltig("Bitte ein Zahlungsziel in Tagen angeben (0–90).");
140	  const sicherheit = Object.prototype.hasOwnProperty.call(SICHERHEITEN, eingabe.sicherheit) ? eingabe.sicherheit : null;
141	  if (!sicherheit) throw new Ungueltig("Bitte die geforderte Sicherheit angeben.");
142	  return { positionen, bindefristBis: new Date(bf).toISOString(), zahlungszielTage, sicherheit, bemerkung: text(eingabe.bemerkung, 1500) };
143	}
