147	/**
148	 * Kontext der Normierung: Referenz-Stundenreihe des Loses (kWh je Stunde, Lieferjahr 1) und Stundenpreiskurve
149	 * (HPFC, €/MWh) des Lieferzeitraums. Aus beiden: lastgewichteter Marktpreis (Spot-Erwartung) und Base-Preis.
150	 */
151	export function normierungKontext(reihe, hpfc) {
152	  let kwh = 0;
153	  let last = 0;
154	  let base = 0;
155	  let n = 0;
156	  for (let i = 0; i < reihe.werte.length; i++) {
157	    const j = Math.round((reihe.startMs + i * 3600000 - hpfc.startMs) / 3600000);
158	    const p = j >= 0 && j < hpfc.werte.length ? hpfc.werte[j] : null;
159	    if (p === null) continue;
160	    kwh += reihe.werte[i];
161	    last += reihe.werte[i] * p;
162	    base += p;
163	    n++;
164	  }
165	  return { kwh, lastgewichtetEurMwh: kwh ? last / kwh : null, baseEurMwh: n ? base / n : null };
166	}
