168	/**
169	 * Position auf das Kundenprofil normieren → erwartete Kosten Energie €/Jahr und ct/kWh.
170	 *  Festpreis:  Menge × Arbeitspreis
171	 *  Spot-Index: Menge × (lastgewichteter Stundenpreis der HPFC + Aufschlag)
172	 *  Tranchen:   Menge × (Base-Terminpreis × Profilfaktor + Aufschlag) – Profilkosten trägt der Kunde
173	 *  jeweils + Grundpreis × 12 + HKN × Menge
174	 */
175	export function positionNormieren(pos, ctx, { marktFaktor = 1 } = {}) {
176	  const kwh = ctx.kwh;
177	  if (!kwh) return null;
178	  let ct;
179	  if (pos.art === "fix") ct = pos.arbeitspreisCt;
180	  else if (pos.art === "spot") ct = (ctx.lastgewichtetEurMwh * marktFaktor) / 10 + pos.aufschlagCt;
181	  else ct = (ctx.lastgewichtetEurMwh * marktFaktor) / 10 + pos.aufschlagCt; // Tranchen: Erwartungswert über die Beschaffung
182	  const eur = (kwh * (ct + (pos.hknCt || 0))) / 100 + (pos.grundpreisEurMonat || 0) * 12;
183	  return { eurJahr: Math.round(eur), ctKwh: rund((eur / kwh) * 100, 3) };
184	}
