186	/** Preisrisiko je Struktur (Anteil der Marktbewegung, der beim Kunden ankommt) */
187	export const MARKT_EXPOSITION = { fix: 0, tranchen: 0.5, spot: 1 };
188	
189	/**
190	 * Angebote vergleichen: alle Positionen aller (gültigen) Angebote normieren, Ranking nach €/Jahr,
191	 * Abstand zum Besten, Sensitivität bei Marktbewegungen (±%).
192	 * angebote: [{id, lieferantId, positionen, …}], produkte: Varianten der Ausschreibung
193	 * @returns {{zeilen: [{angebotId, lieferantId, produktId, produkt, art, eurJahr, ctKwh, rang, abstandProzent, sensitivitaet: {"-20": eur, …}}], bester}}
194	 */
195	export function angeboteVergleichen(angebote = [], produkte = [], ctx, { szenarien = [-30, -15, 15, 30] } = {}) {
196	  const zeilen = [];
197	  for (const a of angebote) {
198	    for (const pos of a.positionen || []) {
199	      const p = produkte.find((x) => x.id === pos.produktId);
200	      if (!p) continue;
201	      const norm = positionNormieren(pos, ctx);
202	      if (!norm) continue;
203	      const sens = {};
204	      for (const s of szenarien) {
205	        const f = 1 + (s / 100) * MARKT_EXPOSITION[p.art];
206	        sens[s] = positionNormieren(pos, ctx, { marktFaktor: f }).eurJahr;
207	      }
208	      zeilen.push({ angebotId: a.id, lieferantId: a.lieferantId, runde: a.runde, produktId: p.id, produkt: produktLabel(p), art: p.art, laufzeitJahre: p.laufzeitJahre, ...norm, sensitivitaet: sens, positionen: pos });
209	    }
210	  }
211	  zeilen.sort((x, y) => x.eurJahr - y.eurJahr);
212	  const best = zeilen[0]?.eurJahr ?? null;
213	  zeilen.forEach((z, i) => {
214	    z.rang = i + 1;
215	    z.abstandProzent = best ? rund(((z.eurJahr - best) / best) * 100, 2) : 0;
216	  });
217	  return { zeilen, bester: zeilen[0] || null, szenarien };
218	}
