220	/** Bestes Angebot je Lieferant (günstigste Position) – Grundlage für Rang/Abstand in Runde 2 */
221	export function besteJeLieferant(vergleich) {
222	  const je = new Map();
223	  for (const z of vergleich.zeilen) if (!je.has(z.lieferantId)) je.set(z.lieferantId, z);
224	  return [...je.values()];
225	}
