227	/**
228	 * Hinweis für einen Lieferanten in der Folgerunde nach der konfigurierten Regel – NIE mit Namen anderer Bieter.
229	 * @returns {null | {regel, text, rang?, von?, abstandProzent?, bestpreisCt?}}
230	 */
231	export function bestpreisHinweis(regel, lieferantId, vergleichVorrunde) {
232	  if (!vergleichVorrunde || regel === "aus" || !BESTPREIS_REGELN[regel]) return null;
233	  const liste = besteJeLieferant(vergleichVorrunde);
234	  const eigen = liste.find((z) => z.lieferantId === lieferantId);
235	  const best = liste[0];
236	  if (!best) return null;
237	  const fmt = (x, s = 2) => Number(x).toLocaleString("de-DE", { minimumFractionDigits: s, maximumFractionDigits: s });
238	  if (regel === "bestpreis") return { regel, bestpreisCt: best.ctKwh, text: `Bestes normiertes Angebot der Vorrunde: ${fmt(best.ctKwh, 3)} ct/kWh (auf das Profil des Loses, inkl. Grundpreis).` };
239	  if (!eigen) return { regel, text: "Sie haben in der Vorrunde kein Angebot abgegeben." };
240	  const rang = liste.indexOf(eigen) + 1;
241	  if (regel === "rang") return { regel, rang, von: liste.length, text: `Ihr bestes Angebot lag in der Vorrunde auf Rang ${rang} von ${liste.length}.` };
242	  const abstand = rund(((eigen.eurJahr - best.eurJahr) / best.eurJahr) * 100, 2);
243	  return { regel, abstandProzent: abstand, text: abstand <= 0 ? "Ihr Angebot war in der Vorrunde das günstigste." : `Ihr bestes Angebot lag in der Vorrunde ${fmt(abstand)} % über dem besten Angebot.` };
244	}
