256	/**
257	 * Anonymisiertes Profil eines Loses (ein Kunde oder Pool) für Lieferanten.
258	 * Eingabe: Kundenprofile [{reihe, kennzahlen, land, spannungsebene, messart, abnahmestellen}]
259	 * Ausgabe NUR: Summen/gerundete Kennzahlen, normiertes Wochenprofil (Anteile, 7×24), Monatsanteile, Anzahl Stellen,
260	 * Länder, Spannungsebenen/Messarten (Häufigkeit). Keine Namen, Orte, PLZ, IDs, keine Rohzeitreihe.
261	 */
262	export function profilAnonymisieren(kunden = [], { ortszeitFn } = {}) {
263	  const summe = { kwh: 0, spitze: 0 };
264	  const woche = Array.from({ length: 7 }, () => new Array(24).fill(0));
265	  const wocheN = Array.from({ length: 7 }, () => new Array(24).fill(0));
266	  const monate = new Array(12).fill(0);
267	  let stellen = 0;
268	  const laender = {};
269	  const ebenen = {};
270	  const messarten = {};
271	  let gesamtSpitze = 0;
272	  let peakKwh = 0;
273	  // Pool-Spitze aus der Summenreihe (gleichzeitige Last), nicht Summe der Einzelspitzen
274	  const n = Math.max(0, ...kunden.map((k) => k.reihe?.werte?.length || 0));
275	  const summenReihe = new Float64Array(n);
276	  const start = kunden[0]?.reihe?.startMs ?? 0;
277	  for (const k of kunden) {
278	    const w = k.reihe?.werte || [];
279	    for (let i = 0; i < w.length; i++) summenReihe[i] += w[i];
280	    stellen += Math.max(1, k.abnahmestellen || 1);
281	    if (k.land) laender[k.land] = (laender[k.land] || 0) + 1;
282	    if (k.spannungsebene) ebenen[k.spannungsebene] = (ebenen[k.spannungsebene] || 0) + 1;
283	    if (k.messart) messarten[k.messart] = (messarten[k.messart] || 0) + 1;
284	  }
285	  for (let i = 0; i < n; i++) {
286	    const x = summenReihe[i];
287	    summe.kwh += x;
288	    gesamtSpitze = Math.max(gesamtSpitze, x);
289	    if (ortszeitFn) {
290	      const o = ortszeitFn(start + i * 3600000);
291	      woche[o.wochentag][o.stunde] += x;
292	      wocheN[o.wochentag][o.stunde]++;
293	      monate[o.monat] += x;
294	      if (o.wochentag < 5 && o.stunde >= 8 && o.stunde < 20) peakKwh += x;
295	    }
296	  }
297	  const mw = woche.map((r, t) => r.map((s, h) => (wocheN[t][h] ? s / wocheN[t][h] : 0)));
298	  const mwMittel = mittel(mw.flat()) || 1;
299	  const jahresMwh = summe.kwh / 1000;
300	  return {
301	    anzahlKunden: kunden.length > 1 ? `${kunden.length} Kunden (Pool)` : "1 Kunde",
302	    abnahmestellen: stellen,
303	    jahresMengeMwh: r10(jahresMwh, jahresMwh >= 1000 ? 50 : 10),
304	    spitzeKw: r10(gesamtSpitze, 10),
305	    benutzungsstunden: gesamtSpitze > 0 ? r10(summe.kwh / gesamtSpitze, 50) : null,
306	    peakAnteilProzent: summe.kwh ? Math.round((peakKwh / summe.kwh) * 100) : null,
307	    wochenprofil: mw.map((r) => r.map((x) => rund(x / mwMittel, 2))), // Faktor zum Mittel, ohne Absolutwerte
308	    monatsanteileProzent: monate.map((m) => (summe.kwh ? rund((m / summe.kwh) * 100, 1) : 0)),
309	    laender,
310	    spannungsebenen: ebenen,
311	    messarten,
312	  };
313	}
