 80	/** Beginn eines Ortszeit-Monats „JJJJ-MM“ in UTC-ms (Mitternacht MEZ/MESZ) */
 81	export function monatsBeginnMs(monat) {
 82	  const [j, m] = monat.split("-").map(Number);
 83	  // Mitternacht Ortszeit = 22 Uhr (MESZ) bzw. 23 Uhr (MEZ) UTC des Vortags
 84	  const sommer = Date.UTC(j, m - 1, 1) - 2 * H;
 85	  return ortszeit(sommer).stunde === 0 ? sommer : sommer + H;
