 99	/**
100	 * Viertelstunden- oder Stundenwerte → Stundenmittel. punkte: [{t (ms), eurMwh}] aufsteigend.
101	 * @returns {[{t, eurMwh, n}]} t = Stundenbeginn (UTC-ms)
102	 */
103	export function stundenwerte(punkte = []) {
104	  const m = new Map();
105	  for (const p of punkte) {
106	    if (!Number.isFinite(p?.eurMwh) || !Number.isFinite(p?.t)) continue;
107	    const t = Math.floor(p.t / H) * H;
108	    const e = m.get(t) || { t, s: 0, n: 0 };
109	    e.s += p.eurMwh;
110	    e.n++;
111	    m.set(t, e);
112	  }
113	  return [...m.values()].sort((a, b) => a.t - b.t).map((e) => ({ t: e.t, eurMwh: e.s / e.n, n: e.n }));
114	}
