116	/** Auflösung einer Reihe in Minuten (Median der Abstände) */
117	export function aufloesungMin(punkte = []) {
118	  const d = [];
119	  for (let i = 1; i < Math.min(punkte.length, 500); i++) d.push(punkte[i].t - punkte[i - 1].t);
120	  d.sort((a, b) => a - b);
121	  return d.length ? Math.round(d[Math.floor(d.length / 2)] / 60000) : 60;
122	}
