124	/** Relative Solar-Einspeisung einer Stunde (0–1, Sonnenhöhe mit Jahresgang) – für Capture-Preise */
125	export function solarGewicht(ms, lat = 50.9, lon = 10.2) {
126	  const d = new Date(ms + H / 2);
127	  const doy = Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 1)) / TAG) + 1;
128	  const phi = (lat * Math.PI) / 180;
129	  const dekl = ((23.44 * Math.PI) / 180) * Math.sin((2 * Math.PI * (284 + doy)) / 365);
130	  const utcH = d.getUTCHours() + d.getUTCMinutes() / 60;
131	  const ha = ((utcH + lon / 15 - 12) * 15 * Math.PI) / 180;
132	  const sinEl = Math.sin(phi) * Math.sin(dekl) + Math.cos(phi) * Math.cos(dekl) * Math.cos(ha);
133	  return sinEl > 0.02 ? sinEl : 0;
134	}
