136	/**
137	 * Kennzahlen einer Menge von Stundenwerten.
138	 * @returns {base, peak, offpeak, min, max, negativ, stunden, capture, captureRate, stdAbw}
139	 */
140	export function kennzahlen(stunden = [], zone = "DE") {
141	  const z = ZONEN[zone] || ZONEN.DE;
142	  const alle = [];
143	  const peak = [];
144	  const off = [];
145	  let negativ = 0;
146	  let min = null;
147	  let max = null;
148	  let sw = 0;
149	  let swp = 0;
150	  for (const s of stunden) {
151	    const p = s.eurMwh;
152	    alle.push(p);
153	    (istPeak(s.t) ? peak : off).push(p);
154	    if (p < 0) negativ++;
155	    if (!min || p < min.eurMwh) min = { t: s.t, eurMwh: p };
156	    if (!max || p > max.eurMwh) max = { t: s.t, eurMwh: p };
157	    const w = solarGewicht(s.t, z.lat, z.lon);
158	    sw += w;
159	    swp += w * p;
160	  }
161	  const base = mittel(alle);
162	  const capture = sw > 0 ? swp / sw : null;
163	  return {
164	    stunden: alle.length,
165	    base: rund(base),
166	    peak: rund(mittel(peak)),
167	    offpeak: rund(mittel(off)),
168	    min,
169	    max,
170	    negativ,
171	    capture: rund(capture),
172	    captureRate: base && capture !== null && base > 0 ? rund(capture / base, 3) : null,
173	    stdAbw: rund(stdAbw(alle)),
174	  };
175	}
