177	/** Kennzahlen je Monat: [{monat, …kennzahlen}] */
178	export function monatsKennzahlen(stunden = [], zone = "DE") {
179	  const je = new Map();
180	  for (const s of stunden) {
181	    const m = monatVon(s.t);
182	    if (!je.has(m)) je.set(m, []);
183	    je.get(m).push(s);
184	  }
185	  return [...je.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([monat, liste]) => ({ monat, ...kennzahlen(liste, zone) }));
186	}
