188	/** Kennzahlen je Kalenderjahr: [{jahr, vollstaendig, …}] */
189	export function jahresKennzahlen(stunden = [], zone = "DE") {
190	  const je = new Map();
191	  for (const s of stunden) {
192	    const j = ortszeit(s.t).jahr;
193	    if (!je.has(j)) je.set(j, []);
194	    je.get(j).push(s);
