199	/** Tagesmittel (Base) je Tag: [{tag, base, peak, min, max, negativ}] */
200	export function tageswerte(stunden = []) {
201	  const je = new Map();
202	  for (const s of stunden) {
203	    const t = tagVon(s.t);
204	    if (!je.has(t)) je.set(t, []);
205	    je.get(t).push(s);
206	  }
207	  return [...je.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([tag, liste]) => {
