209	    const pk = liste.filter((x) => istPeak(x.t)).map((x) => x.eurMwh);
210	    return { tag, base: rund(mittel(p)), peak: pk.length ? rund(mittel(pk)) : null, min: rund(Math.min(...p)), max: rund(Math.max(...p)), negativ: p.filter((x) => x < 0).length };
211	  });
212	}
