214	/**
215	 * Volatilität: Standardabweichung der Stundenpreise, der Tagesbase-Änderungen (€/MWh) und
216	 * mittlere Tagesspanne (Max − Min). Log-Renditen sind wegen negativer Preise nicht sinnvoll.
217	 */
218	export function volatilitaet(stunden = []) {
219	  const tage = tageswerte(stunden);
220	  const diff = [];
221	  for (let i = 1; i < tage.length; i++) diff.push(tage[i].base - tage[i - 1].base);
