230	/** Negative Stunden je Monat und längste Folge */
231	export function negativeStunden(stunden = []) {
232	  let laengste = 0;
233	  let lauf = 0;
234	  const jeMonat = {};
235	  for (const s of stunden) {
236	    if (s.eurMwh < 0) {
237	      lauf++;
238	      laengste = Math.max(laengste, lauf);
239	      const m = monatVon(s.t);
240	      jeMonat[m] = (jeMonat[m] || 0) + 1;
241	    } else lauf = 0;
242	  }
243	  return { gesamt: Object.values(jeMonat).reduce((a, b) => a + b, 0), laengsteFolge: laengste, jeMonat };
244	}
