264	/** Produktcode prüfen und Lieferzeitraum ermitteln: „Cal-27“, „Q1-27“, „M11-26“ → {art, von:"JJJJ-MM", bis:"JJJJ-MM", monate} */
265	export function produktZeitraum(code) {
266	  const m = RE_PRODUKT.exec(String(code || "").trim());
