270	  if (m[1][0] === "Q") {
271	    const q = Number(m[1][1]);
272	    const v = (q - 1) * 3 + 1;
273	    return { code: m[0], art: "quartal", jahr, von: `${jahr}-${String(v).padStart(2, "0")}`, bis: `${jahr}-${String(v + 2).padStart(2, "0")}`, monate: 3 };
274	  }
275	  const mo = String(Number(m[1].slice(1))).padStart(2, "0");
