279	/** Handelbare Standardprodukte ab Stichtag: nächste 6 Monate, 6 Quartale, 3 Kalenderjahre */
280	export function standardProdukte(stichtag = new Date().toISOString().slice(0, 10)) {
281	  const [j, mo] = stichtag.split("-").map(Number);
282	  const out = [];
283	  let mj = j;
284	  let mm = mo;
285	  for (let i = 0; i < 6; i++) {
286	    mm++;
287	    if (mm > 12) {
288	      mm = 1;
289	      mj++;
290	    }
291	    out.push(`M${String(mm).padStart(2, "0")}-${String(mj).slice(2)}`);
292	  }
293	  let qj = j;
294	  let q = Math.ceil(mo / 3);
295	  for (let i = 0; i < 6; i++) {
296	    q++;
297	    if (q > 4) {
298	      q = 1;
299	      qj++;
300	    }
301	    out.push(`Q${q}-${String(qj).slice(2)}`);
302	  }
303	  for (let i = 1; i <= 3; i++) out.push(`Cal-${String(j + i).slice(2)}`);
304	  return out;
305	}
