114	    const k = s > 0 ? monatKwh[m] / s : 0;
115	    for (let t = a; t < b; t += H) {
116	      const o = ortszeit(t);
117	      werte[Math.round((t - startMs) / H)] = Math.max(0, form[o.wochentag][o.stunde]) * k;
118	    }
119	  }
120	  // Zusätzliche PV (geplant bzw. im Bau durch ÖKOVOLT) und Speicher
121	  const pv = { erzeugtKwh: 0, eigenverbrauchKwh: 0, speicherKwh: 0 };
122	  if (pvKwp > 0) {
123	    const z = zone === "AT" ? { lat: 47.8, lon: 14 } : { lat: 50.9, lon: 10.2 };
124	    let wSum = 0;
125	    const w = new Float64Array(n);
126	    for (let i = 0; i < n; i++) {
127	      w[i] = solarGewicht(startMs + i * H, z.lat, z.lon);
128	      wSum += w[i];
129	    }
130	    const jahrKwh = pvKwp * spezErtrag;
131	    let soc = 0;
132	    const kap = Math.max(0, speicherKwh);
133	    for (let i = 0; i < n; i++) {
134	      const erz = wSum > 0 ? Math.min(pvKwp * 0.85, (jahrKwh * w[i]) / wSum) : 0;
135	      pv.erzeugtKwh += erz;
136	      const direkt = Math.min(erz, werte[i]);
137	      let rest = werte[i] - direkt;
138	      let ueber = erz - direkt;
139	      if (kap > 0) {
140	        const laden = Math.min(ueber, kap - soc, kap * 0.5);
141	        soc += laden * 0.95;
142	        ueber -= laden;
143	        const entladen = Math.min(rest, soc, kap * 0.5);
144	        soc -= entladen;
145	        rest -= entladen;
146	        pv.speicherKwh += entladen;
147	      }
148	      pv.eigenverbrauchKwh += werte[i] - rest;
149	      werte[i] = rest;
150	    }
151	  }
152	  const summe = werte.reduce((a, b) => a + b, 0);
153	  return { startMs, werte, quelle: hatLastgang ? "lastgang" : "synthetisch", jahresKwh: rund(summe, 0), pv: { erzeugtKwh: rund(pv.erzeugtKwh, 0), eigenverbrauchKwh: rund(pv.eigenverbrauchKwh, 0), speicherKwh: rund(pv.speicherKwh, 0) } };
154	}
