156	/** Summe mehrerer Stundenreihen gleichen Jahres (Pool) */
157	export function reihenSumme(reihen = []) {
158	  if (!reihen.length) return null;
159	  const n = Math.max(...reihen.map((r) => r.werte.length));
160	  const werte = new Float64Array(n);
161	  for (const r of reihen) for (let i = 0; i < r.werte.length; i++) werte[i] += r.werte[i];
162	  return { startMs: reihen[0].startMs, werte, quelle: "pool", jahresKwh: rund(werte.reduce((a, b) => a + b, 0), 0) };
163	}
164	
165	/** Profilkennzahlen einer Stundenreihe; mit Preisen zusätzlich Profilfaktor (lastgewichteter Preis / Base) */
166	export function profilKennzahlen(reihe, preise = null) {
167	  const { werte, startMs } = reihe;
168	  let summe = 0;
169	  let spitze = 0;
170	  let peak = 0;
171	  let tag = 0;
172	  let we = 0;
173	  let pSum = 0;
174	  let pLast = 0;
175	  let pn = 0;
176	  const sortiert = [];
177	  for (let i = 0; i < werte.length; i++) {
178	    const t = startMs + i * H;
179	    const x = werte[i];
180	    summe += x;
181	    spitze = Math.max(spitze, x);
182	    sortiert.push(x);
183	    if (istPeak(t)) peak += x;
184	    const o = ortszeit(t);
185	    if (o.stunde >= 8 && o.stunde < 17) tag += x;
186	    if (o.wochentag >= 5) we += x;
187	    const p = preise ? preisBei(preise, t) : null;
188	    if (p !== null) {
189	      pSum += p;
190	      pn++;
191	      pLast += p * x;
192	    }
193	  }
194	  sortiert.sort((a, b) => a - b);
195	  const base = pn ? pSum / pn : null;
196	  const lastPreis = summe > 0 && pn ? pLast / summe : null;
197	  return {
198	    jahresKwh: rund(summe, 0),
199	    spitzeKw: rund(spitze, 1),
200	    grundlastKw: rund(sortiert[Math.floor(sortiert.length * 0.05)] || 0, 1),
201	    benutzungsstunden: spitze > 0 ? Math.round(summe / spitze) : 0,
202	    peakAnteil: summe > 0 ? rund(peak / summe, 3) : 0,
203	    tagAnteil: summe > 0 ? rund(tag / summe, 3) : 0,
204	    wochenendeAnteil: summe > 0 ? rund(we / summe, 3) : 0,
205	    lastgewichteterPreis: rund(lastPreis),
206	    basePreis: rund(base),
207	    profilfaktor: base && lastPreis !== null && base > 0 ? rund(lastPreis / base, 3) : null,
208	  };
209	}
