211	/** Preis (€/MWh) zu einem Zeitpunkt aus {startMs, werte} (HPFC) oder Stundenliste [{t,eurMwh}] (über Map) */
212	function preisBei(preise, t) {
213	  if (preise.werte) {
214	    const i = Math.round((t - preise.startMs) / H);
215	    return i >= 0 && i < preise.werte.length ? preise.werte[i] : null;
216	  }
217	  if (!preise._map) Object.defineProperty(preise, "_map", { value: new Map(preise.map((p) => [p.t, p.eurMwh])), enumerable: false });
218	  const p = preise._map.get(t);
219	  return p === undefined ? null : p;
220	}
