224	/** Kosten Spot-Index: Σ Last × (Preis + Aufschlag) → {eur, ctKwh, mwh} */
225	export function kostenSpot(reihe, preise, aufschlagCt = 0) {
226	  let eur = 0;
227	  let kwh = 0;
228	  for (let i = 0; i < reihe.werte.length; i++) {
229	    const p = preisBei(preise, reihe.startMs + i * H);
230	    if (p === null) continue;
231	    const x = reihe.werte[i];
232	    kwh += x;
233	    eur += (x * (p / 10 + aufschlagCt)) / 100;
234	  }
235	  return { eur: rund(eur, 0), ctKwh: kwh ? rund((eur / kwh) * 100, 3) : null, mwh: rund(kwh / 1000, 1) };
236	}
