238	/** Festpreis: Menge × Arbeitspreis (+ Grundpreis) */
239	export function kostenFix(reihe, ctKwh, grundEurMonat = 0) {
240	  const kwh = reihe.werte.reduce((a, b) => a + b, 0);
241	  const eur = (kwh * ctKwh) / 100 + grundEurMonat * 12;
242	  return { eur: rund(eur, 0), ctKwh: kwh ? rund((eur / kwh) * 100, 3) : null, mwh: rund(kwh / 1000, 1) };
243	}
