245	/**
246	 * Tranchenmodell: `anteil` der Menge wird in n Tranchen zu Terminpreisen (tranchenPreise €/MWh Base) gesichert,
247	 * das Profil (Last − Base-Band) und der Rest laufen über den Spot; Aufschlag des Lieferanten (Strukturierung) je kWh.
248	 */
249	export function kostenTranchen(reihe, preise, { tranchenPreise = [], anteil = 0.8, aufschlagCt = 0.6 } = {}) {
250	  const kwh = reihe.werte.reduce((a, b) => a + b, 0);
251	  const n = reihe.werte.length;
252	  const bandKw = (kwh / n) * anteil; // Base-Band
253	  const tranche = tranchenPreise.length ? mittel(tranchenPreise) : null;
254	  let eur = 0;
255	  for (let i = 0; i < n; i++) {
256	    const p = preisBei(preise, reihe.startMs + i * H);
257	    if (p === null) continue;
258	    const x = reihe.werte[i];
259	    const band = tranche !== null ? bandKw : 0;
260	    // Band zum Tranchenpreis; Differenz (auch Überschuss) zum Spot glattstellen
261	    eur += (band * (tranche ?? 0)) / 1000 + ((x - band) * p) / 1000;
262	    eur += (x * aufschlagCt) / 100;
263	  }
264	  return { eur: rund(eur, 0), ctKwh: kwh ? rund((eur / kwh) * 100, 3) : null, mwh: rund(kwh / 1000, 1), tranchePreis: rund(tranche), anteil };
265	}
266	
267	/**
268	 * Strukturvergleich für einen Kunden: Festpreis vs. Tranchen vs. Spot-Index, jeweils auf dieselbe Stundenreihe.
269	 * preise: Spot-Historie (rückwirkend) oder HPFC (prognostisch). fixCt = Festpreisangebot/-annahme (Energiepreis).
270	 */
271	export function strukturVergleich(reihe, preise, { fixCt, spotAufschlagCt = 0.5, tranchenPreise = [], tranchenAnteil = 0.8, tranchenAufschlagCt = 0.6 } = {}) {
272	  const spot = kostenSpot(reihe, preise, spotAufschlagCt);
273	  const tr = kostenTranchen(reihe, preise, { tranchenPreise, anteil: tranchenAnteil, aufschlagCt: tranchenAufschlagCt });
274	  const fix = Number.isFinite(fixCt) ? kostenFix(reihe, fixCt) : null;
275	  const liste = [fix && { id: "fix", ...STRUKTUREN.fix, ...fix }, { id: "tranchen", ...STRUKTUREN.tranchen, ...tr }, { id: "spot", ...STRUKTUREN.spot, ...spot }].filter(Boolean);
276	  const best = liste.reduce((a, b) => (b.eur < a.eur ? b : a), liste[0]);
277	  return { liste, guenstigste: best?.id || null };
278	}
