282	const iso = (d) => d.toISOString().slice(0, 10);
283	export const tageZwischen = (von, bis) => Math.round((Date.parse(`${bis}T00:00:00Z`) - Date.parse(`${von}T00:00:00Z`)) / TAG);
284	
285	/** Kündigungsstichtag = Vertragsende − Kündigungsfrist (Monate bzw. Wochen) → „JJJJ-MM-TT“ oder null */
286	export function kuendigungsStichtag({ vertragEnde, kuendigungsfristMonate = null, kuendigungsfristWochen = null } = {}) {
287	  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(vertragEnde || ""))) return null;
288	  const d = new Date(`${vertragEnde}T00:00:00Z`);
289	  if (Number.isFinite(kuendigungsfristWochen) && kuendigungsfristWochen > 0) d.setUTCDate(d.getUTCDate() - kuendigungsfristWochen * 7);
290	  else {
291	    const m = Number.isFinite(kuendigungsfristMonate) ? kuendigungsfristMonate : 3;
292	    const tag = d.getUTCDate();
293	    d.setUTCDate(1);
294	    d.setUTCMonth(d.getUTCMonth() - m);
295	    const max = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
296	    d.setUTCDate(Math.min(tag, max));
297	  }
298	  return iso(d);
299	}
