301	/** Alarmstufe (größte Schwelle ≥ Resttage) oder null; abgelaufen → 0 */
302	export function fristAlarmStufe(tage, schwellen = ANNAHMEN_STANDARD.fristAlarmTage) {
303	  if (tage === null || tage === undefined) return null;
304	  if (tage < 0) return 0;
305	  const passend = [...schwellen].sort((a, b) => a - b).find((s) => tage <= s);
306	  return passend ?? null;
307	}
