309	/** Energiepreis eines Vertrags in ct/kWh (bei „Gesamtpreis“ ohne die nicht beeinflussbaren Bestandteile aus markt.js) */
310	export function vertragEnergiepreisCt(v) {
311	  if (!v || !Number.isFinite(v.preisCt)) return null;
312	  if (v.preisArt === "gesamt") {
313	    const fix = STROM.bestandteile.filter((b) => !b.beeinflussbar).reduce((s, b) => s + b.ct, 0);
314	    return rund(Math.max(0, v.preisCt - fix), 3);
315	  }
316	  return v.preisCt;
317	}
