319	/**
320	 * Laufende Wechselanalyse eines Vertrags.
321	 * @param {object} p
322	 *   vertrag {preisCt, preisArt: energie|gesamt, vertragEnde, kuendigungsfristMonate|Wochen, verlaengerungMonate,
323	 *            verlaengerungPreisCt?, jahresKwh}
324	 *   markt   {forwardEurMwh (Base des Folgezeitraums), profilfaktor?, trend {richtung, prozent}, quelleDemo?}
325	 *   annahmen ANNAHMEN_STANDARD (überschreibbar), stichtag „JJJJ-MM-TT“
326	 * @returns {{empfehlung, label, ton, begruendung[], vertragCt, marktCt, deltaCt, deltaProzent, deltaEurJahr,
327	 *            stichtag, tageBisStichtag, alarm, fristVerpasst}}
328	 */
329	export function wechselanalyse({ vertrag = {}, markt = {}, annahmen = {}, stichtag = iso(new Date()) } = {}) {
330	  const a = { ...ANNAHMEN_STANDARD, ...annahmen };
331	  const begruendung = [];
332	  const vertragCt = vertragEnergiepreisCt(vertrag);
333	  const kStichtag = kuendigungsStichtag(vertrag);
334	  const tage = kStichtag ? tageZwischen(stichtag, kStichtag) : null;
335	  const fwd = Number.isFinite(markt.forwardEurMwh) ? markt.forwardEurMwh : null;
336	  const pf = Number.isFinite(markt.profilfaktor) && markt.profilfaktor > 0 ? markt.profilfaktor : null;
337	  const marktCt = fwd !== null ? rund((fwd * (pf || 1)) / 10 + (pf ? 0 : a.profilAufschlagCt) + a.lieferantAufschlagCt + (a.serviceFeeEurMwh || 0) / 10, 3) : null;
338	  const out = { stichtag: kStichtag, tageBisStichtag: tage, alarm: fristAlarmStufe(tage, a.fristAlarmTage), vertragCt, marktCt, deltaCt: null, deltaProzent: null, deltaEurJahr: null, fristVerpasst: tage !== null && tage < 0, begruendung };
339	  const fertig = (id) => ({ ...out, empfehlung: id, label: EMPFEHLUNGEN[id].label, ton: EMPFEHLUNGEN[id].ton });
340	
341	  if (vertragCt === null || marktCt === null || !kStichtag) {
342	    if (vertragCt === null) begruendung.push("Preis des laufenden Vertrags fehlt.");
343	    if (!kStichtag) begruendung.push("Vertragsende bzw. Kündigungsfrist fehlt.");
344	    if (marktCt === null) begruendung.push("Kein Terminpreis für den Folgezeitraum verfügbar (Terminkurve einspielen).");
345	    return fertig("pruefen");
346	  }
347	  out.deltaCt = rund(vertragCt - marktCt, 3);
348	  out.deltaProzent = rund((vertragCt - marktCt) / vertragCt, 4);
349	  out.deltaEurJahr = Number.isFinite(vertrag.jahresKwh) ? rund(((vertragCt - marktCt) / 100) * vertrag.jahresKwh, 0) : null;
350	  const vorteil = out.deltaProzent * 100; // > 0: Markt günstiger als der Vertrag
351	  const fmt = (x) => x.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
352	  begruendung.push(`Vertrag ${fmt(vertragCt)} ct/kWh (Energiepreis) gegenüber Markt ${fmt(marktCt)} ct/kWh (Terminpreis ${fmt(fwd)} €/MWh${pf ? ` × Profilfaktor ${pf.toLocaleString("de-DE")}` : ` + Profilaufschlag ${fmt(a.profilAufschlagCt)} ct`} + Lieferantenaufschlag ${fmt(a.lieferantAufschlagCt)} ct${a.serviceFeeEurMwh ? ` + Servicefee ${fmt(a.serviceFeeEurMwh / 10)} ct` : ""}).`);
353	  if (markt.quelleDemo) begruendung.push("Achtung: Die Terminkurve enthält Demo-Werte – vor einer Entscheidung aktuelle, lizenzierte Kurse einspielen.");
354	
355	  if (out.fristVerpasst) {
356	    const verl = vertrag.verlaengerungMonate ? ` um ${vertrag.verlaengerungMonate} Monate` : "";
357	    begruendung.push(`Kündigungsstichtag ${kStichtag.split("-").reverse().join(".")} ist verstrichen – der Vertrag verlängert sich in der Regel${verl} (Vertrag prüfen). Nächstes Kündigungsfenster vormerken.`);
358	    return fertig("verlaengern");
359	  }
360	  begruendung.push(`Kündigung spätestens am ${kStichtag.split("-").reverse().join(".")} (${tage} Tage).`);
361	  if (vorteil >= a.schwelleProzent) {
362	    begruendung.push(`Der Markt liegt ${fmt(vorteil)} % unter dem Vertrag (Schwelle ${a.schwelleProzent} %) – Angebote jetzt einholen und Preis sichern.`);
363	    if (out.deltaEurJahr) begruendung.push(`Rechnerischer Vorteil rund ${Math.round(out.deltaEurJahr).toLocaleString("de-DE")} € pro Jahr (vor Angeboten der Versorger).`);
364	    return fertig("ausschreiben");
365	  }
366	  if (tage <= a.vorlaufTage) {
367	    begruendung.push(`Weniger als ${a.vorlaufTage} Tage bis zum Stichtag – Ausschreibung (Angebotsfrist, Runde 2, Kundenfreigabe) braucht Vorlauf.`);
368	    if (vorteil < 0 && Number.isFinite(vertrag.verlaengerungPreisCt) && vertrag.verlaengerungPreisCt <= marktCt) {
369	      begruendung.push("Das Verlängerungsangebot des bisherigen Lieferanten liegt unter dem Marktniveau – Verlängerung ist eine gute Option, parallel Vergleichsangebote einholen.");
370	      return fertig("verlaengern");
371	    }
372	    return fertig("ausschreiben");
373	  }
374	  if (vorteil < 0 && Number.isFinite(vertrag.verlaengerungPreisCt) && vertrag.verlaengerungPreisCt <= marktCt) {
375	    begruendung.push("Der Vertrag ist günstiger als der Markt und das Verlängerungsangebot liegt unter dem Marktniveau – verlängern prüfen.");
376	    return fertig("verlaengern");
377	  }
378	  if (markt.trend?.richtung === "fallend" && tage > a.vorlaufTage) {
379	    begruendung.push(`Terminpreise fallen (${fmt((markt.trend.prozent || 0) * 100)} % in den letzten Wochen) und es bleibt Zeit bis zum Stichtag – beobachten, Ausschreibung spätestens ${a.vorlaufTage} Tage vor dem Stichtag starten.`);
380	    return fertig("abwarten");
381	  }
382	  if (tage > a.beobachtenTage) {
383	    begruendung.push(`Mehr als ${a.beobachtenTage} Tage bis zum Stichtag – Markt beobachten; Tranchen können bereits jetzt gesichert werden.`);
384	    return fertig("abwarten");
385	  }
386	  if (markt.trend?.richtung === "steigend") begruendung.push("Terminpreise steigen – Abwarten erhöht das Risiko.");
387	  begruendung.push("Kein deutlicher Marktvorteil, aber das Zeitfenster für eine geordnete Ausschreibung ist offen.");
388	  return fertig("ausschreiben");
389	}
