393	/**
394	 * Beschaffungsstand des Pools je Periode.
395	 * bedarf: [{periode "JJJJ-MM" | "Qn-JJ" | "Cal-JJ", mwh}] – Summe der Kundenmengen je Periode
396	 * tranchen: [{periode, mwh, preisEurMwh, typ, status}] (nur status ≠ storniert)
397	 * marktpreis(periode) → aktueller Terminpreis €/MWh (für Mark-to-Market) oder null
398	 * @returns {{perioden: [{periode, bedarfMwh, gesichertMwh, offenMwh, hedgeQuote, mittelpreis, marktpreis, mtmEur, risikoEur}], summe}}
399	 */
400	export function portfolio({ bedarf = [], tranchen = [], marktpreis = () => null, schockProzent = ANNAHMEN_STANDARD.risikoSchockProzent } = {}) {
401	  const je = new Map();
402	  for (const b of bedarf) je.set(b.periode, { periode: b.periode, bedarfMwh: b.mwh || 0, gesichertMwh: 0, kostenGesichert: 0 });
403	  for (const t of tranchen) {
404	    if (t.status === "storniert") continue;
405	    const e = je.get(t.periode) || { periode: t.periode, bedarfMwh: 0, gesichertMwh: 0, kostenGesichert: 0 };
406	    e.gesichertMwh += t.mwh;
407	    e.kostenGesichert += t.mwh * t.preisEurMwh;
408	    je.set(t.periode, e);
409	  }
410	  const perioden = [...je.values()].map((e) => {
411	    const mp = marktpreis(e.periode);
412	    const mittelpreis = e.gesichertMwh ? e.kostenGesichert / e.gesichertMwh : null;
413	    const offen = Math.max(0, e.bedarfMwh - e.gesichertMwh);
414	    return {
415	      periode: e.periode,
416	      bedarfMwh: rund(e.bedarfMwh, 1),
417	      gesichertMwh: rund(e.gesichertMwh, 1),
418	      offenMwh: rund(offen, 1),
419	      ueberdeckungMwh: rund(Math.max(0, e.gesichertMwh - e.bedarfMwh), 1),
420	      hedgeQuote: e.bedarfMwh > 0 ? rund(Math.min(1, e.gesichertMwh / e.bedarfMwh), 3) : null,
421	      mittelpreis: rund(mittelpreis),
422	      marktpreis: mp,
423	      // Mark-to-Market der gesicherten Mengen: (Markt − Einstand) × Menge (positiv = Tranchen günstiger als heute)
424	      mtmEur: mp !== null && mittelpreis !== null ? rund((mp - mittelpreis) * e.gesichertMwh, 0) : null,
425	      // Risiko der offenen Position: offene Menge × Preisbewegung (Schock in % des Marktpreises)
426	      risikoEur: mp !== null ? rund(offen * mp * (schockProzent / 100), 0) : null,
427	      offeneKostenEur: mp !== null ? rund(offen * mp, 0) : null,
428	    };
429	  });
430	  const s = (k) => perioden.reduce((a, p) => a + (p[k] || 0), 0);
431	  const bedarfMwh = s("bedarfMwh");
432	  const gesichertMwh = perioden.reduce((a, p) => a + Math.min(p.gesichertMwh, p.bedarfMwh || p.gesichertMwh), 0);
433	  return {
434	    perioden,
435	    summe: { bedarfMwh: rund(bedarfMwh, 1), gesichertMwh: rund(gesichertMwh, 1), offenMwh: rund(s("offenMwh"), 1), hedgeQuote: bedarfMwh ? rund(gesichertMwh / bedarfMwh, 3) : null, mtmEur: rund(s("mtmEur"), 0), risikoEur: rund(s("risikoEur"), 0), schockProzent },
436	  };
437	}
