439	/** Bedarf einer Stundenreihe je Quartal: [{periode "Qn-JJ", mwh}] */
440	export function bedarfJeQuartal(reihe) {
441	  const je = {};
442	  for (let i = 0; i < reihe.werte.length; i++) {
443	    const o = ortszeit(reihe.startMs + i * H);
444	    const k = `Q${Math.floor(o.monat / 3) + 1}-${String(o.jahr).slice(2)}`;
445	    je[k] = (je[k] || 0) + reihe.werte[i] / 1000;
446	  }
447	  return Object.entries(je).map(([periode, mwh]) => ({ periode, mwh: rund(mwh, 1) }));
