 24	    stand: spot?.stand,
 25	    gesamt: kennzahlen(jahr, spot?.zone),
 26	    jahre: jahresKennzahlen(stunden, spot?.zone),
 27	    monate,
 28	    tage: tageswerte(stunden).slice(-120),
 29	    aktuell: (spot?.aktuell || []).map((p) => ({ t: p.t, eurMwh: Math.round(p.eurMwh * 100) / 100 })),
