 36	/**
 37	 * Kundenanalyse: Profilkennzahlen und Kosten nach Beschaffungsstruktur rückwirkend (letzte 12 volle Monate der
 38	 * Spot-Historie) und prognostisch (Folgezeitraum nach Vertragsende, Stundenpreiskurve aus Terminkurve + Stundenform),
 39	 * PV/Speicher-Einfluss (geplante Anlage aus dem Vertrag).
 40	 * @param {object} k      Ergebnis energieKunde()
 41	 * @param {object} spot   Ergebnis energieSpot() der Zone des Kunden
 42	 * @param {object[]} kurveEintraege  aktuelle Terminkurve (energieTermin().kurve)
 43	 */
 44	export function kundenAuswertung(k, spot, kurveEintraege = []) {
 45	  const vt = k.vertraege.find((x) => ["aktiv", "gekuendigt"].includes(x.status) && x.quelle !== "zuschlag") || k.vertraege[0] || null;
 46	  const zone = vt?.zone === "AT" ? "AT" : "DE";
 47	  const e = k.einstellungen || {};
 48	  const los = k.los || {};
 49	  const jahresKwh = vt?.jahresKwh || los.jahresKwh || 0;
 50	  const profilId = los.analyse ? los.profilId : vt?.lastprofil || los.profilId || "einschicht";
 51	  const kurve = aktuelleKurve(kurveEintraege);
 52	  const stunden = spot?.stunden || [];
 53	  if (!jahresKwh || !stunden.length) return { fehlt: !jahresKwh ? "Jahresmenge fehlt (Vertrag, Abnahmestelle oder Lastgang pflegen)." : "Keine Spotdaten verfügbar." };
 54	
 55	  // Rückwirkend: letzte 12 vollständige Monate
 56	  const letzteT = stunden[stunden.length - 1].t;
 57	  const o = ortszeit(letzteT - 86400e3 * 2);
 58	  let bisM = `${o.jahr}-${String(o.monat + 1).padStart(2, "0")}`;
 59	  const [bj, bm] = bisM.split("-").map(Number);
 60	  bisM = bm === 1 ? `${bj - 1}-12` : `${bj}-${String(bm - 1).padStart(2, "0")}`; // Vormonat (vollständig)
 61	  let vonM = bisM;
 62	  for (let i = 0; i < 11; i++) {
 63	    const [j, m] = vonM.split("-").map(Number);
 64	    vonM = m === 1 ? `${j - 1}-12` : `${j}-${String(m - 1).padStart(2, "0")}`;
 65	  }
 66	  const basis = { jahresKwh, profilId, analyse: los.analyse, zone };
 67	  const reiheHist = kundenReihe({ ...basis, von: vonM, bis: bisM });
 68	  const vonMs = monatsBeginnMs(vonM);
 69	  const bisMs = monatsBeginnMs(naechsterMonat(bisM));
 70	  const hist = stunden.filter((s) => s.t >= vonMs && s.t < bisMs);
 71	  const histBase = hist.length ? hist.reduce((a, s) => a + s.eurMwh, 0) / hist.length : null;
 72	  const vertragCt = vertragEnergiepreisCt(vt);
 73	  const tranchenHist = histBase ? [histBase * 1.04, histBase * 0.98, histBase * 1.07, histBase * 1.01] : [];
 74	  const rueck = strukturVergleich(reiheHist, hist, { fixCt: vertragCt ?? undefined, spotAufschlagCt: 0.5, tranchenPreise: tranchenHist, tranchenAnteil: 0.8, tranchenAufschlagCt: 0.6 });
 75	
 76	  // Prognose: Folgezeitraum nach Vertragsende (12 Monate)
 77	  const ende = vt?.vertragEnde;
 78	  let pVon = ende ? naechsterMonat(ende.slice(0, 7)) : `${new Date().getUTCFullYear() + 1}-01`;
 79	  if (pVon <= new Date().toISOString().slice(0, 7)) pVon = naechsterMonat(new Date().toISOString().slice(0, 7));
 80	  let pBis = pVon;
 81	  for (let i = 0; i < 11; i++) pBis = naechsterMonat(pBis);
 82	  const form = stundenform(stunden.slice(-8784));
 83	  const hpfc = stundenpreiskurve({ kurve, zone, von: pVon, bis: pBis, form });
 84	  const reiheProg = kundenReihe({ ...basis, von: pVon, bis: pBis });
 85	  const fwdBase = terminPreisZeitraum(kurve, zone, pVon, pBis, "base");
 86	  const marktFixCt = fwdBase ? (profilKennzahlen(reiheProg, hpfc).lastgewichteterPreis || fwdBase) / 10 + (e.lieferantAufschlagCt ?? 1.2) : null;
 87	  const prog = strukturVergleich(reiheProg, hpfc, { fixCt: marktFixCt ?? undefined, spotAufschlagCt: 0.5, tranchenPreise: fwdBase ? [fwdBase] : [], tranchenAnteil: 0.8, tranchenAufschlagCt: 0.6 });
 88	
 89	  // PV/Speicher-Einfluss (geplante Anlage aus dem Vertrag, sonst Beispiel 30 % der Spitze in kWp)
 90	  const kennHist = profilKennzahlen(reiheHist, hist);
 91	  const pvKwp = vt?.pvKwpGeplant || Math.round((kennHist.spitzeKw * 0.8) / 10) * 10;
 92	  const speicherKwh = vt?.speicherKwhGeplant || 0;
 93	  const reihePv = kundenReihe({ ...basis, von: pVon, bis: pBis, pvKwp, speicherKwh });
 94	  const pvSpot = strukturVergleich(reihePv, hpfc, { spotAufschlagCt: 0.5 }).liste.find((x) => x.id === "spot");
 95	  const ohneSpot = prog.liste.find((x) => x.id === "spot");
 96	  const kennPv = profilKennzahlen(reihePv, hpfc);
 97	
 98	  // Monatsmengen und Wochenprofil (für Diagramme)
 99	  const monate = [];
100	  for (let i = 0; i < reiheProg.werte.length; i++) {
101	    const oz = ortszeit(reiheProg.startMs + i * H);
102	    const key = `${oz.jahr}-${String(oz.monat + 1).padStart(2, "0")}`;
103	    const m = monate.find((x) => x.monat === key) || (monate.push({ monat: key, kwh: 0, pvKwh: 0 }), monate[monate.length - 1]);
104	    m.kwh += reiheProg.werte[i];
105	    m.pvKwh += reihePv.werte[i];
106	  }
107	  const woche = Array.from({ length: 7 }, () => new Array(24).fill(0));
108	  const n = Array.from({ length: 7 }, () => new Array(24).fill(0));
109	  for (let i = 0; i < reiheProg.werte.length; i++) {
110	    const oz = ortszeit(reiheProg.startMs + i * H);
111	    woche[oz.wochentag][oz.stunde] += reiheProg.werte[i];
112	    n[oz.wochentag][oz.stunde]++;
113	  }
114	  return {
115	    zone,
116	    profilQuelle: reiheProg.quelle,
117	    kennzahlen: kennHist,
118	    rueckwirkend: { von: vonM, bis: bisM, spotQuelle: spot?.quelle, basePreis: histBase ? Math.round(histBase * 100) / 100 : null, ...rueck },
119	    prognose: { von: pVon, bis: pBis, forwardBase: fwdBase, fehlend: hpfc.fehlend, marktFixCt: marktFixCt ? Math.round(marktFixCt * 1000) / 1000 : null, kennzahlen: profilKennzahlen(reiheProg, hpfc), ...prog },
120	    pv: { kwp: pvKwp, speicherKwh, beispiel: !vt?.pvKwpGeplant, eigenverbrauchKwh: reihePv.pv.eigenverbrauchKwh, erzeugtKwh: reihePv.pv.erzeugtKwh, restKwh: reihePv.jahresKwh, spotOhne: ohneSpot?.eur ?? null, spotMit: pvSpot?.eur ?? null, ctOhne: ohneSpot?.ctKwh ?? null, ctMit: pvSpot?.ctKwh ?? null, profilfaktorMit: kennPv.profilfaktor, profilfaktorOhne: prog.liste && profilKennzahlen(reiheProg, hpfc).profilfaktor },
121	    monate: monate.map((m) => ({ monat: m.monat, mwh: Math.round(m.kwh / 100) / 10, pvMwh: Math.round(m.pvKwh / 100) / 10 })),
122	    wochenprofil: woche.map((r, t) => r.map((s, h) => (n[t][h] ? Math.round((s / n[t][h]) * 10) / 10 : 0))),
123	  };
124	}
