135	import { kundenReihe, reihenSumme, profilKennzahlen } from "./beschaffung.js";
136	import { naechsterMonat, ortszeit, stundenpreiskurve } from "./markt.js";
137	import { normierungKontext, profilAnonymisieren } from "./ausschreibung.js";
138	
139	const CACHE = new Map();
140	const MAX = 40;
141	function gemerkt(key, fn) {
142	  if (CACHE.has(key)) return CACHE.get(key);
143	  const w = fn();
144	  CACHE.set(key, w);
145	  if (CACHE.size > MAX) CACHE.delete(CACHE.keys().next().value);
146	  return w;
147	}
