149	/** Bis-Monat für 12 Monate ab `von` („JJJJ-MM“) */
150	export function zwoelfMonate(von) {
151	  let m = von;
152	  for (let i = 0; i < 11; i++) m = naechsterMonat(m);
153	  return m;
154	}
155	
156	function eintragReihe(e, von, zone) {
157	  return kundenReihe({ von, bis: zwoelfMonate(von), jahresKwh: e.jahresKwh || 0, profilId: e.profilId || "einschicht", analyse: e.analyse || null, pvKwp: e.pvKwp || 0, speicherKwh: e.speicherKwh || 0, zone });
158	}
