160	/** Stundenreihe des Loses (erstes Lieferjahr) */
161	export function losReihe(lose = [], von, zone = "DE") {
162	  const key = `r|${von}|${zone}|${JSON.stringify(lose.map((e) => [e.kundeId, e.jahresKwh, e.profilId, e.pvKwp, e.speicherKwh, !!e.analyse]))}`;
163	  return gemerkt(key, () => reihenSumme(lose.map((e) => eintragReihe(e, von, zone))));
164	}
