166	/** Kurven-Schlüssel (für den Zwischenspeicher): jüngster Handelstag + Anzahl Einträge */
167	const kurvenKey = (kurve) => {
168	  const w = Object.values(kurve);
169	  return `${w.length}|${w.reduce((m, e) => (e.handelstag > m ? e.handelstag : m), "")}|${w.reduce((s, e) => s + e.preisEurMwh, 0).toFixed(2)}`;
170	};
171	
172	/**
173	 * Normierungskontext des Loses: {reihe, hpfc, ctx {kwh, lastgewichtetEurMwh, baseEurMwh}, kennzahlen, fehlend}
174	 * Normierung auf die Peak-/Offpeak-Terminpreise je Monat (ohne Stundenform) – nachvollziehbar und in Frappe gleich.
175	 */
176	export function losKontext({ id, lose, lieferbeginn, zone = "DE" }, kurve) {
177	  const key = `k|${id}|${lieferbeginn}|${zone}|${kurvenKey(kurve)}|${JSON.stringify(lose.map((e) => [e.kundeId, e.jahresKwh, e.profilId, e.pvKwp]))}`;
178	  return gemerkt(key, () => {
179	    const reihe = losReihe(lose, lieferbeginn, zone);
180	    const hpfc = stundenpreiskurve({ kurve, zone, von: lieferbeginn, bis: zwoelfMonate(lieferbeginn), form: null });
181	    const ctx = normierungKontext(reihe, hpfc);
182	    return { reihe, hpfc, ctx, kennzahlen: profilKennzahlen(reihe, hpfc), fehlend: hpfc.fehlend };
183	  });
184	}
