186	/** Anonymisiertes Profil für Lieferanten (nur gerundete Kennzahlen, Anteile, Häufigkeiten) */
187	export function losAnonym({ lose, lieferbeginn, zone = "DE" }) {
188	  const reihe = losReihe(lose, lieferbeginn, zone);
189	  const einzel = lose.map((e) => ({ reihe: { startMs: reihe.startMs, werte: new Float64Array(0) }, land: e.land, spannungsebene: e.spannungsebene, messart: e.messart, abnahmestellen: e.abnahmestellen }));
190	  // Summenreihe als ein „Kunde“ übergeben, Metadaten aus den Einträgen
191	  const anonym = profilAnonymisieren([{ reihe }], { ortszeitFn: ortszeit });
192	  const meta = profilAnonymisieren(einzel, {});
193	  return { ...anonym, anzahlKunden: lose.length > 1 ? `${lose.length} Kunden (Pool)` : "1 Kunde", abnahmestellen: meta.abnahmestellen, laender: meta.laender, spannungsebenen: meta.spannungsebenen, messarten: meta.messarten };
194	}
