207	import { QUELLEN, ZONEN, simulierteSpotpreise, stundenwerte, aufloesungMin } from "./markt.js";
208	
209	const EC = "https://api.energy-charts.info";
210	const CACHE = new Map(); // key → { bis: ms, wert }
211	const TAG = 86400000;
212	
213	function datum(ms) {
214	  return new Date(ms).toISOString().slice(0, 10);
215	}
216	
217	async function holen(bzn, von, bis) {
218	  const url = `${EC}/price?bzn=${encodeURIComponent(bzn)}&start=${von}&end=${bis}`;
219	  const res = await fetch(url, { next: { revalidate: 21600 }, headers: { Accept: "application/json", "User-Agent": "oekoinvest-handelsdesk" }, signal: AbortSignal.timeout(15000) });
220	  if (!res.ok) throw new Error(`${res.status}`);
221	  const j = await res.json();
222	  const punkte = (j.unix_seconds || []).map((s, i) => ({ t: s * 1000, eurMwh: j.price?.[i] })).filter((p) => typeof p.eurMwh === "number" && Number.isFinite(p.eurMwh));
223	  return { punkte, lizenzText: typeof j.license_info === "string" ? j.license_info.slice(0, 300) : "" };
224	}
