226	/**
227	 * Spotpreise einer Zone der letzten `tage` Tage bis einschließlich morgen (sofern veröffentlicht).
228	 * @returns {{zone, quelle: "energycharts"|"simulation", quelleLabel, lizenz, aufloesungMin, stunden: [{t, eurMwh}] (Stundenmittel),
229	 *            aktuell: [{t, eurMwh}] (Originalauflösung ab vorgestern), stand, fehler?}}
230	 */
231	export async function spotReihe(zone = "DE", { tage = 400 } = {}) {
232	  const z = ZONEN[zone] || ZONEN.DE;
233	  const heute = Date.now();
234	  const vonMs = heute - tage * TAG;
235	  const key = `${z.id}|${tage}|${datum(heute)}`;
236	  const c = CACHE.get(key);
237	  if (c && c.bis > heute) return c.wert;
238	  let wert;
239	  try {
240	    const { punkte, lizenzText } = await holen(z.bzn, datum(vonMs), datum(heute + 2 * TAG));
241	    if (punkte.length < 24) throw new Error("zu wenige Werte");
242	    wert = { zone: z.id, quelle: "energycharts", quelleLabel: QUELLEN.energycharts.label, lizenz: lizenzText || QUELLEN.energycharts.lizenz, aufloesungMin: aufloesungMin(punkte), stunden: stundenwerte(punkte), aktuell: punkte.filter((p) => p.t >= heute - 2 * TAG), stand: new Date().toISOString() };
243	  } catch (e) {
244	    const punkte = simulierteSpotpreise({ zone: z.id, vonMs: Date.parse(`${datum(vonMs)}T00:00:00Z`), bisMs: Date.parse(`${datum(heute + TAG)}T22:00:00Z`) });
245	    wert = { zone: z.id, quelle: "simulation", quelleLabel: QUELLEN.simulation.label, lizenz: QUELLEN.simulation.lizenz, aufloesungMin: 60, stunden: punkte, aktuell: punkte.filter((p) => p.t >= heute - 2 * TAG), stand: new Date().toISOString(), fehler: `Energy-Charts nicht erreichbar (${String(e?.message || e).slice(0, 80)}) – Simulation angezeigt.` };
246	  }
247	  CACHE.set(key, { bis: heute + (wert.quelle === "energycharts" ? 3 * 3600e3 : 10 * 60e3), wert });
248	  if (CACHE.size > 8) CACHE.delete(CACHE.keys().next().value);
249	  return wert;
250	}
