182	/**
183	 * Fachliche Hinweise zur Abnahmestelle (keine Fehler): Messart vs. Verbrauch, Kündigungsfenster, § 19, Stromsteuer.
184	 * @returns {[{stufe: "warnung"|"info", text}]}
185	 */
186	export function abnahmestelleHinweise(s, { jetzt, benutzungsstunden } = {}) {
187	  const h = [];
188	  if (!s) return h;
189	  const heute = (jetzt ? new Date(jetzt) : new Date()).toISOString().slice(0, 10);
190	  if (s.land === "DE" && s.messart === "slp" && s.jahresverbrauchKwh > RLM_GRENZE_KWH) h.push({ stufe: "warnung", text: `Über ${RLM_GRENZE_KWH.toLocaleString("de-DE")} kWh/Jahr ist in Deutschland in der Regel eine registrierende Leistungsmessung (RLM) vorgeschrieben – Messart beim Netzbetreiber prüfen.` });
191	  if (s.messart === "slp") h.push({ stufe: "info", text: "Bei SLP-Messung gibt es keinen echten Lastgang – für die Pool-Bewertung genügt die Jahresmenge, eine Lastgang-Analyse ist erst mit RLM oder Smart Meter möglich." });
192	  if (s.vertragEnde) {
193	    const ende = new Date(`${s.vertragEnde}T00:00:00Z`);
194	    const frist = new Date(ende);
195	    frist.setUTCMonth(frist.getUTCMonth() - (s.kuendigungsfristMonate ?? 3));
196	    const fristIso = frist.toISOString().slice(0, 10);
197	    if (s.vertragEnde < heute) h.push({ stufe: "warnung", text: "Vertragsende liegt in der Vergangenheit – ggf. Verlängerung oder Ersatzversorgung zu teuren Konditionen prüfen." });
198	    else if (fristIso < heute) h.push({ stufe: "warnung", text: `Kündigungsfrist abgelaufen (Stichtag ${fristIso.split("-").reverse().join(".")}) – prüfen Sie die automatische Verlängerung.` });
199	    else {
200	      const tage = Math.round((frist - new Date(`${heute}T00:00:00Z`)) / 864e5);
201	      h.push({ stufe: tage < 120 ? "warnung" : "info", text: `Kündigung spätestens am ${fristIso.split("-").reverse().join(".")} (${tage === 1 ? "1 Tag" : `${tage} Tage`}) – Beschaffung für den Pool rechtzeitig vorbereiten.` });
202	    }
203	  }
204	  if (s.land === "DE" && s.stromsteuerEntlastung === null) h.push({ stufe: "info", text: "Produzierendes Gewerbe sowie Land- und Forstwirtschaft können seit 2026 eine Stromsteuer-Entlastung auf 0,05 ct/kWh beantragen (§ 9b StromStG, Antrag beim Hauptzollamt)." });
205	  if (s.land === "DE" && benutzungsstunden && s.jahresverbrauchKwh) {
206	    if (benutzungsstunden >= INTENSIV.stunden && s.jahresverbrauchKwh > INTENSIV.kwh && s.par19 !== "intensiv") h.push({ stufe: "warnung", text: `Mit ${Math.round(benutzungsstunden).toLocaleString("de-DE")} Benutzungsstunden und über 10 GWh kommt ein individuelles Netzentgelt nach § 19 Abs. 2 S. 2 StromNEV in Betracht – Antrag bei der Regulierungsbehörde prüfen.` });
207	  }
208	  return h;
209	}
