218	export const EG_ROLLEN = { bezug: "Bezug (Verbraucher)", einspeisung: "Einspeisung (Erzeuger)", beides: "Bezug und Einspeisung (Prosumer)" };
219	
220	/**
221	 * Teilnahme an einer Energiegemeinschaft bereinigen. Land-spezifische Pflichtangaben:
222	 * DE: MaLo-ID; AT: Zählpunktnummer (Bezug) bzw. zweite Zählpunktnummer für die Einspeisung, Netzbetreiber, Form lokal/regional/BEG;
223	 * CH: Messpunkt, Gemeinde (LEG nur innerhalb einer Gemeinde).
224	 */
225	export function egTeilnahmeBereinigen(d = {}) {
226	  const land = auswahl(d.land, { DE: 1, AT: 1, CH: 1 }, "DE");
227	  const t = {
228	    land,
229	    form: auswahl(d.form, EG_FORMEN[land], ""),
230	    rolle: auswahl(d.rolle, EG_ROLLEN, "bezug"),
231	    maloId: "",
232	    zaehlpunkt: "",
233	    zaehlpunktEinspeisung: "",
234	    netzbetreiber: text(d.netzbetreiber, 120),
235	    plz: text(d.plz, 10),
236	    ort: text(d.ort, 80),
237	    jahresverbrauchKwh: zahl(d.jahresverbrauchKwh, 0, 1e8),
238	    anlageKwp: zahl(d.anlageKwp, 0, 100000, 1),
239	    smartMeter: jaNein(d.smartMeter),
240	    datenfreigabe: jaNein(d.datenfreigabe),
241	  };
242	  if (!t.form) throw new Ungueltig("Bitte wählen Sie die Form der Energiegemeinschaft.", "form");
243	  if (land === "DE") {
244	    const m = maloPruefen(d.maloId);
245	    if (!m.ok) throw new Ungueltig(m.fehler, "maloId");
246	    t.maloId = m.wert;
247	  } else {
248	    const z = zaehlpunktPruefen(d.zaehlpunkt, land);
249	    if (!z.ok) throw new Ungueltig(z.fehler, "zaehlpunkt");
250	    t.zaehlpunkt = z.wert;
251	    if (t.rolle !== "bezug" && d.zaehlpunktEinspeisung) {
252	      const e = zaehlpunktPruefen(d.zaehlpunktEinspeisung, land);
253	      if (!e.ok) throw new Ungueltig(`Einspeisung: ${e.fehler}`, "zaehlpunktEinspeisung");
254	      if (e.wert === t.zaehlpunkt) throw new Ungueltig("Für Bezug und Einspeisung gibt es in der Regel zwei verschiedene Zählpunkte.", "zaehlpunktEinspeisung");
255	      t.zaehlpunktEinspeisung = e.wert;
256	    }
257	  }
258	  if (!t.netzbetreiber) throw new Ungueltig("Bitte geben Sie Ihren Netzbetreiber an.", "netzbetreiber");
259	  if (!t.plz) throw new Ungueltig("Bitte geben Sie die Postleitzahl der Abnahmestelle an.", "plz");
260	  return t;
261	}
262	
263	/** Hinweise zur Teilnahme (Voraussetzungen je Land) */
264	export function egHinweise(t) {
265	  const h = [];
266	  if (!t) return h;
267	  if (t.land === "AT") {
268	    if (t.smartMeter === false) h.push({ stufe: "warnung", text: "Für die Teilnahme ist ein Smart Meter mit Viertelstundenwerten nötig – beim Netzbetreiber beantragen." });
269	    if (t.datenfreigabe !== true) h.push({ stufe: "info", text: "Die Viertelstundenwerte müssen im Webportal des Netzbetreibers für die Gemeinschaft freigegeben werden (Opt-in)." });
270	    if (t.form === "eeg_lokal") h.push({ stufe: "info", text: "Lokal heißt: alle Teilnehmer hängen am Niederspannungsnetz derselben Trafostation (Netzebenen 6–7) – höchster Netzentgelt-Rabatt." });
271	    if (t.form === "eeg_regional") h.push({ stufe: "info", text: "Regional heißt: Teilnehmer im Mittelspannungsnetz desselben Umspannwerks (zusätzlich Netzebenen 4–5) – geringerer Rabatt als lokal." });
272	    if (t.rolle !== "bezug" && !t.zaehlpunktEinspeisung) h.push({ stufe: "info", text: "Für die Einspeisung ist die Zählpunktnummer der Überschusseinspeisung anzugeben (eigener Zählpunkt)." });
273	  }
274	  if (t.land === "DE") h.push({ stufe: "info", text: "Energy Sharing nach § 42c EnWG ist nach aktuellem Stand zunächst im Netzgebiet eines Verteilnetzbetreibers möglich; ein Netzentgeltvorteil ist derzeit nicht vorgesehen. Ein intelligentes Messsystem ist Voraussetzung." });
275	  if (t.land === "CH" && t.form === "leg") h.push({ stufe: "info", text: "Eine LEG ist auf das Gebiet einer Gemeinde und auf dieselbe Netzebene bzw. denselben Verteilnetzbetreiber beschränkt; die Netznutzung wird reduziert abgerechnet." });
276	  return h;
277	}
278	
279	export { Ungueltig as EnergieUngueltig };

