  1	// src/lib/plattform/fach/lastgang.js
  2	//
  3	// Lastgang-Import und -Analyse für Unternehmen (Reststrom-Pool, Contracting). Reine Funktionen ohne Node-Importe –
  4	// im Browser (Vorschau) und auf dem Server (maßgeblich) identisch. Getestet in scripts/plattform-test-fach-kapital.mjs.
  5	//
  6	// Parser (lastgangParsen):
  7	//  - Trennzeichen ; \t , – Dezimalkomma oder -punkt, BOM, Kopf- und Metadatenzeilen (Zählpunkt, Einheit …)
  8	//  - Zeitstempel: „TT.MM.JJJJ hh:mm[:ss]“, „TT.MM.JJ“, „JJJJ-MM-TT[T ]hh:mm[:ss]“ mit oder ohne Offset/Z,
  9	//    Datum und Uhrzeit in getrennten Spalten, Von-/Bis-Spalten (Beginn zählt), Zeitstempel am Intervallende
 10	//  - Einheit aus Kopf/Metadaten: W, kW, MW (Leistungsmittelwert) bzw. Wh, kWh, MWh (Energie je Intervall), OBIS
 11	//    1.29.x = Energie je Periode, 1.4.x/1.5.x = Leistung; sonst Vorgabe des Nutzers, sonst Annahme kW (mit Hinweis)
 12	//  - Zeitumstellung (MEZ/MESZ, EU-Regel – gilt für DE, AT, CH): doppelte Stunde im Oktober wird der Reihe nach
 13	//    MESZ → MEZ zugeordnet; fehlende Stunde im März ist KEINE Lücke. Enthält die Datei Zeiten aus der
 14	//    übersprungenen Stunde, ist sie durchgehend in MEZ (Winterzeit) geführt – dann wird so gerechnet.
 15	//  - Raster 15 min in UTC; Stundenwerte werden auf Viertelstunden verteilt (gleiche Leistung)
 16	//  - Plausibilisierung: Lücken, doppelte Werte, negative Werte, Ausreißer, Nullphasen
 17	//
 18	// Analyse (lastgangAnalyse): Jahresverbrauch (bei < 12 Monaten hochgerechnet), Spitze mit Zeitpunkt,
 19	// Benutzungsstunden, Grund-/Mittagslast, Wochenprofil (7 × 24), Monate, Lastdauerlinie, Anteil Solarstunden,
 20	// PV-Deckungspotenzial je Anlagengröße (Viertelstundensimulation mit Regionsertrag und Monatsverteilung aus
 21	// markt.js, Sonnenstandsprofil wie im Anlagen-Simulator) und Pool-Ersparnis (rechner/reststrom.js).
 22	
 23	import { ALLGEMEIN, REGIONEN } from "../../invest/markt.js";
 24	import { berechneReststrom, LASTPROFILE } from "../../rechner/reststrom.js";
 25	
 26	const SLOT_MS = 900000;
 27	const TAG_MS = 86400000;
 28	const MAX_ZEILEN = 120000; // > 3 Jahre Viertelstunden
 29	
 30	// ---------------------------------------------------------------- Zeit (MEZ/MESZ, EU-Regel)
 31	
 32	function letzterSonntagUtc(jahr, monat) {
 33	  const d = new Date(Date.UTC(jahr, monat + 1, 0));
 34	  return d.getUTCDate() - d.getUTCDay();
 35	}
 36	/** Beginn/Ende der Sommerzeit in UTC-ms (01:00 UTC am letzten Sonntag im März/Oktober) */
 37	export function sommerzeitGrenzen(jahr) {
 38	  return { beginn: Date.UTC(jahr, 2, letzterSonntagUtc(jahr, 2), 1), ende: Date.UTC(jahr, 9, letzterSonntagUtc(jahr, 9), 1) };
 39	}
 40	/** Versatz Ortszeit – UTC in Stunden für einen UTC-Zeitpunkt */
 41	export function versatzH(ms) {
 42	  const { beginn, ende } = sommerzeitGrenzen(new Date(ms).getUTCFullYear());
 43	  return ms >= beginn && ms < ende ? 2 : 1;
 44	}
 45	/** Ortszeit-Bestandteile eines UTC-Zeitpunkts */
 46	export function ortszeit(ms) {
 47	  const d = new Date(ms + versatzH(ms) * 3600000);
 48	  return { jahr: d.getUTCFullYear(), monat: d.getUTCMonth(), tag: d.getUTCDate(), stunde: d.getUTCHours(), minute: d.getUTCMinutes(), wochentag: (d.getUTCDay() + 6) % 7 /* 0 = Mo */, datum: d.toISOString().slice(0, 10) };
 49	}
 50	
 51	/** Lokale Wandzeit → UTC. `zweite` = zweites Auftreten in der doppelten Oktober-Stunde. Liefert {ms, art} */
 52	function ortszeitZuUtc(j, mo, t, h, mi, { zweite = false, nurMez = false } = {}) {
 53	  const wand = Date.UTC(j, mo, t, h, mi);
 54	  if (nurMez) return { ms: wand - 3600000, art: "normal" };
 55	  const { beginn, ende } = sommerzeitGrenzen(j);
 56	  // übersprungene Stunde im März: Wandzeit 02:00–02:59 existiert nicht
 57	  const sprungVon = beginn + 3600000; // 02:00 MEZ-Wandzeit = beginn + 1 h
 58	  if (wand >= sprungVon && wand < sprungVon + 3600000) return { ms: wand - 3600000, art: "luecke" };
 59	  // doppelte Stunde im Oktober: Wandzeit 02:00–02:59 existiert zweimal
 60	  const doppelVon = ende + 3600000; // 02:00 Wandzeit
 61	  if (wand >= doppelVon && wand < doppelVon + 3600000) return { ms: wand - (zweite ? 3600000 : 7200000), art: "doppelt" };
 62	  const sommer = wand - 7200000 >= beginn && wand - 7200000 < ende;
 63	  return { ms: wand - (sommer ? 7200000 : 3600000), art: "normal" };
 64	}
 65	
 66	// ---------------------------------------------------------------- Parser
 67	
 68	const RE_DE = /^(\d{1,2})\.(\d{1,2})\.(\d{2}|\d{4})(?:[ T]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/;
 69	const RE_ISO = /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?)?\s*(Z|[+-]\d{2}:?\d{2})?$/i;
 70	const RE_ZEIT = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/;
 71	
 72	function datumLesen(s) {
 73	  const x = s.trim().replace(/^"|"$/g, "");
 74	  let m = RE_DE.exec(x);
 75	  if (m) {
 76	    const j = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
 77	    return { j, mo: Number(m[2]) - 1, t: Number(m[1]), h: m[4] !== undefined ? Number(m[4]) : null, mi: m[5] !== undefined ? Number(m[5]) : null, offset: null };
 78	  }
 79	  m = RE_ISO.exec(x);
 80	  if (m) {
 81	    let offset = null;
 82	    if (m[7]) offset = m[7].toUpperCase() === "Z" ? 0 : (m[7][0] === "-" ? -1 : 1) * (Number(m[7].slice(1, 3)) * 60 + Number(m[7].slice(-2)));
 83	    return { j: Number(m[1]), mo: Number(m[2]) - 1, t: Number(m[3]), h: m[4] !== undefined ? Number(m[4]) : null, mi: m[5] !== undefined ? Number(m[5]) : null, offset };
 84	  }
 85	  return null;
 86	}
 87	function zeitLesen(s) {
 88	  const m = RE_ZEIT.exec(s.trim().replace(/^"|"$/g, ""));
 89	  return m ? { h: Number(m[1]), mi: Number(m[2]) } : null;
 90	}
 91	function zahlLesen(s) {
 92	  let x = String(s).trim().replace(/^"|"$/g, "").replace(/\s/g, "");
 93	  if (!x || !/^[+-]?[\d.,]+(e[+-]?\d+)?$/i.test(x)) return null;
 94	  if (x.includes(",") && x.includes(".")) x = x.lastIndexOf(",") > x.lastIndexOf(".") ? x.replace(/\./g, "").replace(",", ".") : x.replace(/,/g, "");
 95	  else if (x.includes(",")) x = x.replace(",", ".");
 96	  const n = Number(x);
 97	  return Number.isFinite(n) ? n : null;
 98	}
 99	
100	/** Einheit aus einem Text (Kopf, Metadaten) erkennen */
101	export function einheitErkennen(text) {
102	  const t = String(text || "").toLowerCase();
103	  if (/1[.-]29\.\d|1-1:1\.29|\b[12]\.8\.\d\s*\(delta|energie je (periode|intervall)/.test(t)) return "kWh";
104	  if (/1[.-][45]\.\d|1-1:1\.[45]\b/.test(t)) return "kW";
105	  if (/\bmwh\b/.test(t)) return "MWh";
106	  if (/\bkwh\b/.test(t)) return "kWh";
107	  if (/(^|[^k])\bwh\b/.test(t)) return "Wh";
108	  if (/\bmw\b/.test(t)) return "MW";
109	  if (/\bkw\b/.test(t)) return "kW";
110	  if (/\[w\]|\(w\)|\bin w\b|\bwatt\b/.test(t)) return "W";
111	  return null;
112	}
113	const EINHEITEN = { W: { energie: false, faktor: 0.001 }, kW: { energie: false, faktor: 1 }, MW: { energie: false, faktor: 1000 }, Wh: { energie: true, faktor: 0.001 }, kWh: { energie: true, faktor: 1 }, MWh: { energie: true, faktor: 1000 } };
114	export const EINHEIT_IDS = Object.keys(EINHEITEN);
115	
116	function trennzeichen(zeilen) {
117	  const probe = zeilen.slice(0, 40).join("\n");
118	  const zaehl = (c) => probe.split(c).length - 1;
119	  const s = zaehl(";");
120	  const t = zaehl("\t");
121	  if (s >= Math.max(t, 1)) return ";";
122	  if (t >= 1) return "\t";
123	  return ",";
124	}
125	
126	function feldSplit(zeile, sep) {
127	  if (!zeile.includes('"')) return zeile.split(sep);
128	  const out = [];
129	  let akt = "";
130	  let inQ = false;
131	  for (const c of zeile) {
132	    if (c === '"') inQ = !inQ;
133	    else if (c === sep && !inQ) {
134	      out.push(akt);
135	      akt = "";
136	    } else akt += c;
137	  }
138	  out.push(akt);
139	  return out;
140	}
141	
142	/**
143	 * CSV-Text eines Lastgangs parsen.
144	 * @param {string} text
145	 * @param {{einheit?: string}} optionen einheit = Vorgabe des Nutzers (W|kW|MW|Wh|kWh|MWh), überschreibt die Erkennung
146	 * @returns {{ok, fehler?, startMs, kw: number[] (NaN = Lücke), n, intervallMin, einheit, einheitQuelle, zeitbasis, hinweise, statistik}}
147	 */
148	export function lastgangParsen(text, { einheit: vorgabe = null } = {}) {
149	  const roh = String(text || "").replace(/^﻿/, "");
150	  const zeilen = roh.split(/\r?\n/).map((z) => z.trimEnd()).filter((z) => z.trim());
151	  if (zeilen.length < 10) return { ok: false, fehler: "Die Datei enthält zu wenige Zeilen für einen Lastgang." };
152	  if (zeilen.length > MAX_ZEILEN) return { ok: false, fehler: `Die Datei ist zu groß (mehr als ${MAX_ZEILEN.toLocaleString("de-DE")} Zeilen). Bitte höchstens drei Jahre hochladen.` };
153	  const sep = trennzeichen(zeilen);
154	  const hinweise = [];
155	
156	  // Kopf- und Metadatenzeilen sammeln (alles vor der ersten Datenzeile)
157	  let kopf = "";
158	  let kopfFelder = null;
159	  let erste = -1;
160	  for (let i = 0; i < Math.min(zeilen.length, 60); i++) {
161	    const f = feldSplit(zeilen[i], sep);
162	    if (datumLesen(f[0] || "") && f.slice(1).some((x) => zahlLesen(x) !== null)) {
163	      erste = i;
164	      break;
165	    }
166	    kopf += ` ${zeilen[i]}`;
167	    if (f.length >= 2) kopfFelder = f.map((x) => x.trim().replace(/^"|"$/g, ""));
168	  }
169	  if (erste < 0) return { ok: false, fehler: "Keine Datenzeilen erkannt. Erwartet: Datum/Uhrzeit in der ersten Spalte und ein Messwert (z. B. „01.01.2025 00:15;12,5“)." };
170	
171	  // Spaltenaufbau aus der ersten Datenzeile
172	  const probe = feldSplit(zeilen[erste], sep).map((x) => x.trim());
173	  const d0 = datumLesen(probe[0]);
174	  let zeitSpalte = -1;
175	  let endeSpalte = -1;
176	  let spalte = 1;
177	  if (d0.h === null) {
178	    if (zeitLesen(probe[1] || "")) {
179	      zeitSpalte = 1;
180	      spalte = 2;
181	      if (zeitLesen(probe[2] || "")) {
182	        endeSpalte = 2;
183	        spalte = 3;
184	      }
185	    } else return { ok: false, fehler: "Uhrzeit fehlt – erwartet wird ein Viertelstunden- oder Stundenwert je Zeile." };
186	  } else if (probe[1] && datumLesen(probe[1])?.h !== null && datumLesen(probe[1])) {
187	    endeSpalte = 1; // Von-/Bis-Zeitstempel
188	    spalte = 2;
189	  } else if (zeitLesen(probe[1] || "")) {
190	    endeSpalte = 1; // „01.01.2025 00:00;00:15;Wert“
191	    spalte = 2;
192	  }
193	  // Wertspalte: Kopf mit Einheit/Stichwort bevorzugen, sonst erste Zahl nach den Zeitspalten
194	  let wertSpalte = -1;
195	  if (kopfFelder) {
196	    const idx = kopfFelder.findIndex((k, i) => i >= spalte && /(kwh|kw|mwh|\bmw\b|\bwh\b|\bw\b|wert|leistung|verbrauch|energie|bezug|1\.29|1\.5\.0|1\.4\.0)/i.test(k));
197	    if (idx >= 0 && zahlLesen(probe[idx] ?? "") !== null) wertSpalte = idx;
198	  }
199	  if (wertSpalte < 0) wertSpalte = probe.findIndex((x, i) => i >= spalte && zahlLesen(x) !== null);
200	  if (wertSpalte < 0) return { ok: false, fehler: "Keine Messwert-Spalte gefunden." };
201	
202	  // Einheit
203	  const kopfEinheit = kopfFelder?.[wertSpalte] ? einheitErkennen(kopfFelder[wertSpalte]) || einheitErkennen(kopf) : einheitErkennen(kopf);
204	  let einheit = kopfEinheit;
205	  let einheitQuelle = kopfEinheit ? "datei" : "annahme";
206	  if (vorgabe && EINHEITEN[vorgabe]) {
207	    if (kopfEinheit && kopfEinheit !== vorgabe) hinweise.push({ stufe: "warnung", text: `In der Datei steht „${kopfEinheit}“, gewählt wurde „${vorgabe}“ – es wird mit „${vorgabe}“ gerechnet.` });
208	    einheit = vorgabe;
209	    einheitQuelle = "vorgabe";
210	  }
211	  if (!einheit) {
212	    einheit = "kW";
213	    hinweise.push({ stufe: "warnung", text: "Einheit nicht erkannt – die Werte werden als Leistungsmittelwerte in kW gelesen. Wählen Sie sonst die Einheit aus (z. B. kWh je Viertelstunde)." });
214	  }
215	  const endeBeschriftet = /\b(bis|ende|intervallende|end)\b/i.test(kopfFelder?.[0] || "") && endeSpalte < 0;
216	
217	  // Zeilen lesen (Ortszeit oder mit Offset)
218	  const roheWerte = [];
219	  let fehlerZeilen = 0;
220	  for (let i = erste; i < zeilen.length; i++) {
221	    const f = feldSplit(zeilen[i], sep);
222	    const d = datumLesen(f[0] || "");
223	    const w = zahlLesen(f[wertSpalte] ?? "");
224	    if (!d || w === null) {
225	      fehlerZeilen++;
226	      continue;
227	    }
228	    let h = d.h;
229	    let mi = d.mi;
230	    if (zeitSpalte >= 0) {
231	      const z = zeitLesen(f[zeitSpalte] || "");
232	      if (!z) {
233	        fehlerZeilen++;
234	        continue;
235	      }
236	      h = z.h;
237	      mi = z.mi;
238	    }
239	    if (h === 24 && mi === 0) {
240	      // 24:00 = Intervallende am Tagesende
241	      const n = new Date(Date.UTC(d.j, d.mo, d.t + 1));
242	      roheWerte.push({ j: n.getUTCFullYear(), mo: n.getUTCMonth(), t: n.getUTCDate(), h: 0, mi: 0, offset: d.offset, w });
