L270+299	        } catch {
L271+299	          /* Strom geschlossen */
L272+299	        }
L273+299	      };
L274+299	      ctrl.enqueue(enc.encode(`retry: 5000\n\n`));
L275+299	      senden();
L276+299	      timer = setInterval(senden, intervallMs);
L277+299	      ping = setInterval(() => {
L278+299	        try {
L279+299	          ctrl.enqueue(enc.encode(`: ping ${Date.now()}\n\n`));
