 70	export async function getGeneration() {
 71	  try {
 72	    const j = await holeJson(`${EC}/public_power?country=de&start=${berlinDatum(-1)}&end=${berlinDatum(1)}`, 900);
 73	    const zeiten = (j.unix_seconds || []).map((s) => s * 1000);
 74	    const reihe = (name) => j.production_types?.find((p) => p.name === name)?.data || [];
 75	    const summe = (...namen) =>
 76	      zeiten.map((_, i) => namen.reduce((acc, n) => acc + (Number(reihe(n)[i]) || 0), 0));
 77	
 78	    const serien = {
 79	      solar: reihe("Solar"),
 80	      windOnshore: reihe("Wind onshore"),
 81	      windOffshore: reihe("Wind offshore"),
 82	      biomasse: reihe("Biomass"),
 83	      wasser: summe("Hydro Run-of-River", "Hydro water reservoir"),
 84	      braunkohle: reihe("Fossil brown coal / lignite"),
 85	      steinkohle: reihe("Fossil hard coal"),
 86	      gas: reihe("Fossil gas"),
 87	      // Rest der öffentlichen Nettoerzeugung (Müll, Öl, Grubengas, Geothermie, Pumpspeicher, Sonstige)
 88	      sonstige: summe("Waste", "Fossil oil", "Fossil coal-derived gas", "Geothermal", "Others", "Hydro pumped storage"),
 89	      last: reihe("Load"),
 90	      eeAnteil: reihe("Renewable share of load"),
 91	    };
 92	
 93	    // Letzter Zeitpunkt mit Solar- UND Lastwert
 94	    let idx = -1;
 95	    for (let i = zeiten.length - 1; i >= 0; i--) {
 96	      if (serien.solar[i] != null && serien.last[i] != null) { idx = i; break; }
 97	    }
 98	    return { quelle: "Energy-Charts (Fraunhofer ISE)", zeiten, serien, idx };
 99	  } catch (e) {
100	    console.error("energy-charts power:", e.message);
101	    return { quelle: null, zeiten: [], serien: {}, idx: -1 };
102	  }
103	}
