106	export async function getEnergySnapshot() {
107	  const [preise, erzeugung] = await Promise.all([getSpotPrices(), getGeneration()]);
108	  const jetzt = Date.now();
109	  const schritt = preise.aufloesungMin * 60000;
110	
111	  const heuteStr = berlinDatum(0);
112	  const tagVon = (t) => new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(new Date(t));
113	  const heute = preise.punkte.filter((p) => tagVon(p.t) === heuteStr);
114	  const morgen = preise.punkte.filter((p) => tagVon(p.t) === berlinDatum(1));
115	  const aktuell = preise.punkte.find((p) => p.t <= jetzt && jetzt < p.t + schritt) || null;
116	
117	  const stat = (arr) => {
118	    if (!arr.length) return null;
119	    const werte = arr.map((p) => p.eurMwh);
120	    const min = arr.reduce((a, b) => (b.eurMwh < a.eurMwh ? b : a));
121	    const max = arr.reduce((a, b) => (b.eurMwh > a.eurMwh ? b : a));
122	    return { avg: werte.reduce((a, b) => a + b, 0) / werte.length, min, max, negativ: werte.filter((w) => w < 0).length };
123	  };
124	
125	  const { serien, idx, zeiten } = erzeugung;
126	  const wert = (s) => (idx >= 0 && serien[s] ? Number(serien[s][idx]) || 0 : null);
127	  const wind = idx >= 0 ? (wert("windOnshore") || 0) + (wert("windOffshore") || 0) : null;
128	
129	  return {
130	    stand: new Date().toISOString(),
131	    preis: {
132	      quelle: preise.quelle,
133	      aufloesungMin: preise.aufloesungMin,
134	      aktuell,
135	      heute: stat(heute),
136	      morgen: stat(morgen),
137	      punkte: preise.punkte,
138	    },
139	    erzeugung: {
140	      quelle: erzeugung.quelle,
141	      zeitpunkt: idx >= 0 ? zeiten[idx] : null,
142	      solarMw: wert("solar"),
143	      windMw: wind,
144	      lastMw: wert("last"),
145	      eeAnteil: wert("eeAnteil"),
146	      solarAnteil: idx >= 0 && wert("last") ? (wert("solar") / wert("last")) * 100 : null,
147	      zeiten,
148	      serien,
149	    },
150	  };
151	}
