 54	/** Deterministischer Zufall je Schlüssel (reproduzierbare Demo-Gebote) */
 55	function zufall(s) {
 56	  let h = 2166136261;
 57	  for (const c of s) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
 58	  return ((h >>> 0) % 10000) / 10000;
 59	}
