 61	function gebotErzeugen(a, lf, runde, ctx, produkte, { faktor = 1 } = {}) {
 62	  const markt = ctx.lastgewichtetEurMwh / 10; // ct/kWh
 63	  const positionen = [];
 64	  for (const p of produkte) {
 65	    const r = zufall(`${a.id}|${lf.id}|${p.id}|${runde}`);
 66	    if (r < 0.12) continue; // nicht jeder bietet jede Variante
 67	    const pos = { produktId: p.id, art: p.art, arbeitspreisCt: null, aufschlagCt: null, grundpreisEurMonat: Math.round(40 + r * 120), hknCt: p.gruen ? Math.round((0.05 + r * 0.15) * 1000) / 1000 : null, mengentoleranzProzent: 20 };
 68	    if (p.art === "fix") pos.arbeitspreisCt = Math.round((markt + (0.9 + r * 1.1) * faktor + (p.laufzeitJahre - 1) * -0.15) * 1000) / 1000;
 69	    else pos.aufschlagCt = Math.round(((p.art === "spot" ? 0.3 : 0.5) + r * 0.5) * faktor * 1000) / 1000;
 70	    positionen.push(pos);
 71	  }
 72	  if (!positionen.length) {
 73	    const p = produkte[0];
 74	    positionen.push({ produktId: p.id, art: p.art, arbeitspreisCt: p.art === "fix" ? Math.round((markt + 1.4) * 1000) / 1000 : null, aufschlagCt: p.art === "fix" ? null : 0.8, grundpreisEurMonat: 90, hknCt: p.gruen ? 0.1 : null, mengentoleranzProzent: 20 });
 75	  }
 76	  return positionen;
 77	}
